INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2e6bd50e-aaf2-4fed-87e7-6120730a0404', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'alert', 'Alert', 'Feedback & Status', NULL, 'mdi-alert-circle-outline', 'components.catalog.alert.description', 'Contextual feedback message with intent colors, optional title, dismiss button and icon slots.', NULL, NULL, 'origam-alert', NULL, 'packages/ds/src/components/Alert/OrigamAlert.vue', 'origam', NULL, NULL, '/stories/?story=components-alert--design', '/docs/components/Alert/OrigamAlert.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.alert.a11y.role_note", "noteFallback": "Alerts with status \"warning\" or \"error\" use role=\"alert\" with aria-live=\"assertive\". Other statuses use role=\"status\" with aria-live=\"polite\"."}, {"noteKey": "components.alert.a11y.close_label_note", "noteFallback": "The close button receives an aria-label from the closeLabel prop, defaulting to the translated \"Close\" string via the locale system."}, {"noteKey": "components.alert.a11y.hover_note", "noteFallback": "The component tracks hover state via @mouseenter/@mouseleave and propagates it via update:hover. Focus visible styles are applied for keyboard navigation."}], "roles": ["alert", "status"], "keyboard": [{"key": "Tab", "actionKey": "components.alert.a11y.key_tab", "actionFallback": "Moves focus to the close button when closable=true."}, {"key": "Enter / Space", "actionKey": "components.alert.a11y.key_close", "actionFallback": "Activates the close button when focused."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---disabled)", "tokenPath": "--origam-alert---background-color", "descriptionKey": "components.alert.tokens.background_color", "descriptionFallback": "Default alert background."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-alert---padding-block-start", "descriptionKey": "components.alert.tokens.padding_block_start", "descriptionFallback": "Default top/bottom block padding."}, {"type": "color", "value": "var(--origam-color__feedback--success---bg)", "tokenPath": "--origam-alert--success---bg", "descriptionKey": "components.alert.tokens.success_bg", "descriptionFallback": "Background for the success status variant."}, {"type": "color", "value": "var(--origam-color__feedback--warning---bg)", "tokenPath": "--origam-alert--warning---bg", "descriptionKey": "components.alert.tokens.warning_bg", "descriptionFallback": "Background for the warning status variant."}, {"type": "color", "value": "var(--origam-color__feedback--danger---bg)", "tokenPath": "--origam-alert--danger---bg", "descriptionKey": "components.alert.tokens.danger_bg", "descriptionFallback": "Background for the danger/error status variant."}, {"type": "dimension", "value": "var(--origam-font__size---2xl)", "tokenPath": "--origam-alert__title---font-size", "descriptionKey": "components.alert.tokens.title_font_size", "descriptionFallback": "Font size of the title area."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"40\" width=\"660\" height=\"160\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"40\" width=\"660\" height=\"160\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.5\"/>\n  <rect x=\"20\" y=\"40\" width=\"4\" height=\"160\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.6\"/>\n  <rect x=\"32\" y=\"56\" width=\"60\" height=\"128\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"62\" y=\"125\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prepend</text>\n  <rect x=\"104\" y=\"56\" width=\"458\" height=\"128\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <rect x=\"116\" y=\"66\" width=\"434\" height=\"34\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"333\" y=\"88\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"600\">Header (icon + title)</text>\n  <rect x=\"116\" y=\"106\" width=\"434\" height=\"64\" rx=\"2\" fill=\"none\"/>\n  <text x=\"333\" y=\"140\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Body / #default slot</text>\n  <rect x=\"570\" y=\"56\" width=\"52\" height=\"128\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"596\" y=\"125\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">close</text>\n  <rect x=\"22\" y=\"196\" width=\"656\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.15))\"/>\n  <circle cx=\"28\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"62\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"62\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"108\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"333\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"333\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"333\" cy=\"114\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"333\" y=\"118\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"574\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"574\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"350\" cy=\"200\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"204\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <text x=\"350\" y=\"230\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">⑦ underlay = absolute layer, decorative</text>\n", "code": "<div class=\"origam-alert\" role=\"status\" aria-live=\"polite\">\n  <span class=\"origam-alert__underlay\" />\n\n  <!-- prepend: icon or avatar -->\n  <div class=\"origam-alert__prepend\">\n    <slot name=\"prepend\" />\n  </div>\n\n  <!-- content: header + body + default slot -->\n  <div class=\"origam-alert__content\">\n    <div class=\"origam-alert__header\">\n      <!-- icon + title -->\n      <span class=\"origam-alert__title\">\n        <slot name=\"title\" />\n      </span>\n    </div>\n    <div class=\"origam-alert__body\">\n      <slot name=\"text\" />\n      <slot name=\"default\" />\n    </div>\n  </div>\n\n  <!-- close button -->\n  <div class=\"origam-alert__close\">\n    <slot name=\"close\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-alert", "num": 1, "descriptionKey": "components.alert.anatomy.root", "descriptionFallback": "Root element. CSS grid with 4 columns: prepend / content / append / close. <code>role=\"alert\"</code> (assertive) for warning/error, <code>role=\"status\"</code> (polite) for info/success."}, {"cls": ".origam-alert__prepend", "num": 2, "descriptionKey": "components.alert.anatomy.prepend", "descriptionFallback": "Leading area (grid-area: prepend). Renders <code>prependIcon</code> or <code>prependAvatar</code>, or the <code>#prepend</code> slot."}, {"cls": ".origam-alert__content", "num": 3, "descriptionKey": "components.alert.anatomy.content", "descriptionFallback": "Content container (grid-area: content). Holds the header (<code>__header</code>) and body (<code>__body</code>)."}, {"cls": ".origam-alert__header", "num": 4, "descriptionKey": "components.alert.anatomy.header", "descriptionFallback": "Header area inside content. Contains the icon and/or title. Rendered only when <code>hasHeader</code> is true."}, {"cls": ".origam-alert__body", "num": 5, "descriptionKey": "components.alert.anatomy.body", "descriptionFallback": "Body area. Contains the <code>#text</code> slot or <code>text</code> prop, plus the <code>#default</code> slot."}, {"cls": ".origam-alert__close", "num": 6, "descriptionKey": "components.alert.anatomy.close", "descriptionFallback": "Close button area (grid-area: close). Rendered only when <code>closable=true</code> or the <code>#close</code> slot is used."}, {"cls": ".origam-alert__underlay", "num": 7, "descriptionKey": "components.alert.anatomy.underlay", "descriptionFallback": "Absolute decorative layer. <code>grid-area: none; position: absolute</code>. Used for the colored border-radius adaptation in the inset border modifier."}], "classes": [{"cls": "origam-alert", "descriptionKey": "components.alert.anatomy.root", "descriptionFallback": "Root grid container. role=\"alert\" or \"status\" based on intent."}, {"cls": "origam-alert__underlay", "descriptionKey": "components.alert.anatomy.underlay", "descriptionFallback": "Absolute decorative underlay layer."}, {"cls": "origam-alert__prepend", "descriptionKey": "components.alert.anatomy.prepend", "descriptionFallback": "Leading icon/avatar zone."}, {"cls": "origam-alert__content", "descriptionKey": "components.alert.anatomy.content", "descriptionFallback": "Main content column."}, {"cls": "origam-alert__header", "descriptionKey": "components.alert.anatomy.header", "descriptionFallback": "Header row inside content (icon + title)."}, {"cls": "origam-alert__title", "descriptionKey": "components.alert.anatomy.title", "descriptionFallback": "Title text element inside the header."}, {"cls": "origam-alert__body", "descriptionKey": "components.alert.anatomy.body", "descriptionFallback": "Body text zone."}, {"cls": "origam-alert__append", "descriptionKey": "components.alert.anatomy.append", "descriptionFallback": "Trailing icon/avatar zone (grid-area: append)."}, {"cls": "origam-alert__close", "descriptionKey": "components.alert.anatomy.close", "descriptionFallback": "Close button container (grid-area: close)."}], "svgDesc": "Schematic of the Alert component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamAlert", "rootClass": "origam-alert", "figcaption": "Anatomy of <code>&lt;origam-alert&gt;</code> — 7 internal parts in a CSS grid (prepend | content | close). The underlay ⑦ is an absolute decorative layer behind the content.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-alert---background-color", "defaultValue": "{color.surface.disabled}", "descriptionKey": "components.alert.css_vars.background_color", "descriptionFallback": "Default alert background color. Overridden by status (warning/success/info/error) and color prop."}, {"name": "--origam-alert---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.alert.css_vars.color", "descriptionFallback": "Default foreground color. Overridden by status colors."}, {"name": "--origam-alert---border-radius", "defaultValue": "{radius.none}", "descriptionKey": "components.alert.css_vars.border_radius", "descriptionFallback": "Border radius. Zero by default; overridden by the rounded prop."}, {"name": "--origam-alert---padding-block-start", "defaultValue": "{space.4}", "descriptionKey": "components.alert.css_vars.padding_block_start", "descriptionFallback": "Top padding. Adjusted by density."}, {"name": "--origam-alert---padding-inline-start", "defaultValue": "{space.4}", "descriptionKey": "components.alert.css_vars.padding_inline_start", "descriptionFallback": "Leading (left) padding. Adjusted by density."}, {"name": "--origam-alert---density", "defaultValue": "0px", "descriptionKey": "components.alert.css_vars.density", "descriptionFallback": "Density offset: comfortable=-8px, default=0px, compact=+8px."}, {"name": "--origam-alert---box-shadow-elevated", "defaultValue": "{shadow.md}", "descriptionKey": "components.alert.css_vars.box_shadow_elevated", "descriptionFallback": "Box shadow for elevated variant (when elevation prop is set)."}, {"name": "--origam-alert__title---font-size", "defaultValue": "{font.size.2xl}", "descriptionKey": "components.alert.css_vars.title_font_size", "descriptionFallback": "Font size of the title area."}, {"name": "--origam-alert__title---font-weight", "defaultValue": "{font.weight.medium}", "descriptionKey": "components.alert.css_vars.title_font_weight", "descriptionFallback": "Font weight of the title text."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.alert.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.alert.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed alertStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.alert.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.alert.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.alert.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.alert.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.alert.playground.color", "defaultValue": "success", "labelFallback": "Color / Intent"}, {"kind": "text", "prop": "title", "labelKey": "components.alert.playground.title", "defaultValue": "Alert title", "labelFallback": "Title"}, {"kind": "text", "prop": "text", "labelKey": "components.alert.playground.text", "defaultValue": "This is an alert message.", "labelFallback": "Text"}, {"kind": "switch", "prop": "closable", "labelKey": "components.alert.playground.closable", "defaultValue": false, "labelFallback": "Closable"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-check-circle", "value": "mdi-check-circle"}, {"label": "mdi-alert-circle", "value": "mdi-alert-circle"}, {"label": "mdi-alert", "value": "mdi-alert"}, {"label": "mdi-information", "value": "mdi-information"}], "labelKey": "components.alert.playground.prepend_icon", "defaultValue": "mdi-information", "labelFallback": "Prepend icon"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "pill", "value": "pill"}], "labelKey": "components.alert.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}]}, "previewVariants": [{"label": "success", "props": {"text": "Operation completed.", "color": "success", "title": "Success", "prependIcon": "mdi-check-circle"}}, {"label": "danger", "props": {"text": "Something went wrong.", "color": "danger", "title": "Error", "prependIcon": "mdi-alert-circle"}}, {"label": "warning", "props": {"text": "Review your settings.", "color": "warning", "title": "Warning", "prependIcon": "mdi-alert"}}, {"label": "info", "props": {"text": "Update available.", "color": "info", "title": "Info", "prependIcon": "mdi-information"}}, {"label": "closable", "props": {"text": "Click × to close.", "color": "primary", "title": "Dismissable", "closable": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('07aca150-f168-4f37-a492-c4e0f29f93ec', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'app', 'App', 'Layout & Structure', NULL, 'mdi-application', 'components.catalog.app.description', 'Application shell root. Thin wrapper over OrigamLayout that sets the page background and default text colour; all descendant components inherit the colour cascade.', NULL, NULL, 'origam-app', NULL, 'packages/ds/src/components/App/OrigamApp.vue', 'origam', NULL, NULL, '/stories/?story=components-app--design', '/docs/components/App/OrigamApp.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.app.a11y.landmark_note", "noteFallback": "App is a structural shell — it does not carry an ARIA role itself. Place semantic landmarks (<header>, <main>, <nav>, <footer>) inside the default slot."}, {"noteKey": "components.app.a11y.color_note", "noteFallback": "The color prop sets the root text colour via CSS inheritance. Ensure sufficient contrast between the chosen color and bgColor values."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.app.a11y.key_tab", "actionFallback": "Moves focus through interactive children inside the app shell."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-app---background-color", "descriptionKey": "components.app.tokens.background_color", "descriptionFallback": "Default app background. References the semantic surface default."}, {"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-app---color", "descriptionKey": 