nd__matches\">\n    <!-- #match slot × N -->\n    <origam-bracket-match class=\"origam-bracket-round__match\" />\n    <origam-bracket-match class=\"origam-bracket-round__match\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-bracket-round", "num": 1, "descriptionKey": "components.bracket_round.anatomy.root", "descriptionFallback": "Root flex column container. role=\"group\" with aria-labelledby pointing to the title. Direction modifier switches to row for vertical mode."}, {"cls": ".origam-bracket-round__title", "num": 2, "descriptionKey": "components.bracket_round.anatomy.title", "descriptionFallback": "Round title <h3>. Visible only when showRoundTitle=true. Gets a computed id for aria-labelledby."}, {"cls": ".origam-bracket-round__matches", "num": 3, "descriptionKey": "components.bracket_round.anatomy.matches", "descriptionFallback": "Flex column container for match cards. justify-content: space-around distributes matches evenly. Gap driven by --origam-bracket-round---match-gap."}], "classes": [{"cls": "origam-bracket-round", "descriptionKey": "components.bracket_round.anatomy.root", "descriptionFallback": "Root flex column container."}, {"cls": "origam-bracket-round__title", "descriptionKey": "components.bracket_round.anatomy.title", "descriptionFallback": "Round title heading <h3>."}, {"cls": "origam-bracket-round__matches", "descriptionKey": "components.bracket_round.anatomy.matches", "descriptionFallback": "Match cards container with space-around justification."}, {"cls": "origam-bracket-round__match", "descriptionKey": "components.bracket_round.anatomy.match", "descriptionFallback": "Applied to each OrigamBracketMatch inside the round."}, {"cls": "origam-bracket-round--final", "descriptionKey": "components.bracket_round.anatomy.final", "descriptionFallback": "Added to the last round (index === totalRounds - 1)."}, {"cls": "origam-bracket-round--direction-horizontal", "descriptionKey": "components.bracket_round.anatomy.horizontal", "descriptionFallback": 