INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a1edbaa6-0b98-4cd5-8e2c-7a02e835c746', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'card', 'Card', 'Surface', NULL, 'mdi-card-outline', 'components.catalog.card.description', 'Versatile surface container with title, subtitle, image asset, text body, footer slots, link support, loading states and ripple interaction.', NULL, NULL, 'origam-card', NULL, 'packages/ds/src/components/Card/OrigamCard.vue', 'origam', NULL, NULL, '/stories/?story=components-card--design', '/docs/components/Card/OrigamCard.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.card.a11y.disabled_tabindex", "noteFallback": "When disabled=true, tabindex=\"-1\" is set to remove the card from the tab order."}, {"noteKey": "components.card.a11y.link_semantics", "noteFallback": "When href or to is set, the card root renders as <a> with proper link semantics. The ripple v-ripple directive triggers on the native click event."}, {"noteKey": "components.card.a11y.focus_visible", "noteFallback": "Focus-visible outline is applied via :focus-visible in the component SCSS — visible for keyboard navigation, not mouse clicks."}, {"noteKey": "components.card.a11y.overlay_hidden", "noteFallback": "The __overlay and __underlay spans are aria-hidden (inert layers)."}, {"noteKey": "components.card.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to ensure accessible foreground/background contrast when color is set."}, {"noteKey": "components.card.a11y.loader", "noteFallback": "The OrigamProgress inside the loader slot has role=\"progressbar\". OrigamSkeleton is ari