ls---height", "defaultValue": "50px", "descriptionKey": "components.carousel.css_vars.controls_height", "descriptionFallback": "Height of the controls strip."}, {"name": "--origam-carousel__controls---z-index", "defaultValue": "{zIndex.raised}", "descriptionKey": "components.carousel.css_vars.controls_z_index", "descriptionFallback": "Z-index of the controls strip, ensuring it renders above slide content."}, {"name": "--origam-carousel__controls-item---opacity", "defaultValue": "0.5", "descriptionKey": "components.carousel.css_vars.controls_item_opacity", "descriptionFallback": "Default icon opacity inside a pagination dot."}, {"name": "--origam-carousel__controls-item---opacity-active", "defaultValue": "1", "descriptionKey": "components.carousel.css_vars.controls_item_opacity_active", "descriptionFallback": "Icon opacity inside the active pagination dot."}, {"name": "--origam-carousel__progress---position-top", "defaultValue": "0", "descriptionKey": "components.carousel.css_vars.progress_position_top", "descriptionFallback": "Top offset of the progress bar. Set to auto and provide bottom to move it."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.carousel.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.carousel.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed carousel styles."}, {"name": "id", "type": "string", "descriptionKey": "components.carousel.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.carousel.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.carousel.exposed.un