llet.css_vars.axis_label_font_size", "descriptionFallback": "Font size of axis labels."}, {"name": "--origam-chart__title---font-size", "defaultValue": "1.125rem", "descriptionKey": "components.chart_bullet.css_vars.title_font_size", "descriptionFallback": "Font size of the chart title."}, {"name": "--origam-chart__title---font-weight", "defaultValue": "600", "descriptionKey": "components.chart_bullet.css_vars.title_font_weight", "descriptionFallback": "Font weight of the chart title."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_bullet.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_bullet.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_bullet.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "select", "prop": "barColor", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "ghost", "value": "ghost"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_bullet.playground.bar_color", "defaultValue": "", "labelFallback": "Bar Color"}, {"kind": "select", "prop": "targetColor", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "ghost", "value": "ghost"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_bullet.playground.target_color", "defaultValue": "", "labelFallback": "Target Color"}, {"kind": "switch", "prop": "showAxis", "labelKey": "components.chart_bullet.playground.show_axis", "defaultValue": true, "labelFallback": "Show Axis"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_bullet.playground.show_legend", "defaultValue": false, "labelFallback": "Show Legend"}, {"kind": "switch", "prop": "showTooltip", "labelKey": "components.chart_bullet.playground.show_tooltip", "defaultValue": true, "labelFallback": "Show Tooltip"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('21861553-660f-45c1-b21c-bd75778f98c8', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'chart-candlestick', 'ChartCandlestick', 'Data Visualization', NULL, 'mdi-candlestick', 'components.catalog.chart_candlestick.description', 'OHLC candlestick chart engine. Renders one candle per datum — a rectangular body between open and close plus a thin wick from low to high. Bullish (close ≥ open) and bearish candles use distinct intent colours.', NULL, NULL, 'origam-chart-candlestick', NULL, 'packages/ds/src/components/Chart/OrigamChartCandlestick.vue', 'origam', NULL, NULL, '/stories/?story=components-chart-candlestick--design', '/docs/components/Chart/OrigamChartCandlestick.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_candlestick.a11y.root_note", "noteFallback": "Root element has role=\"figure\" with aria-label set to the title prop or \"candlestick chart\"."}, {"noteKey": "components.chart_candlestick.a11y.svg_note", "noteFallback": "SVG has role=\"img\" with <title> and <desc> elements describing the data."}, {"noteKey": "components.chart_candlestick.a11y.candle_note", "noteFallback": "Each candle has role=\"button\", tabindex=0, and aria-label describing date, direction, open, high, low, close."}, {"noteKey": "components.chart_candlestick.a11y.reduced_motion_note", "noteFallback": "All animations are disabled under prefers-reduced-motion: reduce."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_candlestick.a11y.key_tab", "actionFallback": "Moves focus between interactive candles."}, {"key": "Enter / Space", "actionKey": "components.chart_candlestick.a11y.key_activate", "actionFallback": "Activates the focused candle and fires point-click."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-chart---background-color", "descriptionKey": "components.chart_candlestick.tokens.background_color", "descriptionFallback": "Root chart background."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-chart---padding", "descriptionKey": "components.chart_candlestick.tokens.padding", "descriptionFallback": "Chart inner padding."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-chart__grid---color", "descriptionKey": "components.chart_candlestick.tokens.grid_color", "descriptionFallback": "Grid line colour."}, {"type": "color", "value": "var(--origam-color__surface---inverse)", "tokenPath": "--origam-chart__tooltip---background-color", "descriptionKey": "components.chart_candlestick.tokens.tooltip_bg", "descriptionFallback": "Tooltip background."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"640\" height=\"260\" fill=\"var(--origam-color__surface---sunken,#fbf5ff)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"12\" width=\"608\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__surface---raised,#fff)\" stroke=\"var(--origam-color__border---default,rgba(124,58,237,0.3))\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"36\" font-size=\"11\" fill=\"var(--origam-color__text---primary,#1e1b4b)\" font-family=\"sans-serif\">Chart title</text>\n  <circle cx=\"24\" cy=\"30\" r=\"8\" fill=\"var(--origam-color__action--primary---bg,#7c3aed)\"/>\n  <text x=\"24\" y=\"34\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"16\" y=\"60\" width=\"608\" height=\"148\" rx=\"3\" fill=\"var(--origam-color__surface---raised,#fff)\" stro