iptionKey": "components.checkbox.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.checkbox.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}, {"name": "styleId", "type": "string", "descriptionKey": "components.checkbox.exposed.style_id", "descriptionFallback": "Unique style-sheet ID for scoping injected CSS."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.checkbox.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}, {"label": "compact", "value": "compact"}], "labelKey": "components.checkbox.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "indeterminate", "labelKey": "components.checkbox.playground.indeterminate", "defaultValue": false, "labelFallback": "Indeterminate"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.checkbox.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.checkbox.playground.readonly", "defaultValue": false, "labelFallback": "Readonly"}, {"kind": "switch", "prop": "error", "labelKey": "components.checkbox.playground.error", "defaultValue": false, "labelFallback": "Error"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7fbd0d6d-ce7f-4e43-9f07-363ee851d053', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'checkbox-btn', 'CheckboxBtn', 'Form & Input', NULL, 'mdi-checkbox-marked-outline', 'components.catalog.checkbox_btn.description', 'Low-level checkbox control without the Input frame. Wraps OrigamSelectionControl to expose just the interactive icon and optional label, without hint or validation message wrappers.', NULL, NULL, 'origam-checkbox-btn', NULL, 'packages/ds/src/components/Checkbox/OrigamCheckboxBtn.vue', 'origam', NULL, NULL, '/stories/?story=components-checkboxbtn--design', '/docs/components/Checkbox/OrigamCheckboxBtn.html', 'checkbox', '{"a11y": {"notes": [{"noteKey": "components.checkbox_btn.a11y.indeterminate", "noteFallback": "When indeterminate=true, aria-checked=\"mixed\" is set on the underlying input element."}, {"noteKey": "components.checkbox_btn.a11y.disabled", "noteFallback": "Disabled state sets the native disabled attribute (the underlying input is a real <input type=\"checkbox\">)."}, {"noteKey": "components.checkbox_btn.a11y.focus", "noteFallback": "Focus-visible outline is applied via CSS to the selection control. Controlled by OrigamSelectionControl."}], "roles": ["checkbox"], "keyboard": [{"key": "Space", "actionKey": "components.checkbox_btn.a11y.key_space", "actionFallback": "Toggles the checked state (native checkbox behaviour)."}, {"key": "Tab", "actionKey": "components.checkbox_btn.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"24\" width=\"668\" height=\"96\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"16\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-checkbox-btn ①</text>\n  <rect x=\"32\" y=\"40\" width=\"636\" height=\"64\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"100\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-selection-control ②</text>\n  <rect x=\"300\" y=\"50\" width=\"44\" height=\"44\" rx=\"22\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"322\" y=\"76\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon ③</text>\n  <rect x=\"360\" y=\"60\" width=\"120\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, #f3f4f6)\" stroke=\"var(--origam-color__border---default, #e5e7eb)\" stroke-width=\"1\"/>\n  <text x=\"420\" y=\"76\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">label / #label ④</text>\n  <text x=\"350\" y=\"148\" font-size=\"8.5\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"sans-serif\">Delegates all selection logic to OrigamSelectionControl (trueIcon / falseIcon / indeterminateIcon)</text>\n", "code": "<!-- root class carries BEM + host style -->\n<origam-selection-control\n  class=\"origam-checkbox-btn\"\n  type=\"checkbox\"\n  :true-icon=\"trueIcon\"\n  :false-icon=\"falseIcon\"\n  :aria-checked=\"indeterminate ? ''mixed'' : undefined\"\n>\n  <template #default>\n    <slot name=\"default\" />\n  </template>\n  <template #label>\n    <slot name=\"label\" />\n  </template>\n  <template #input=\"{ props, icon, textColorStyles, backgroundColorStyles, model }\">\n    <slot name=\"input\" v-bind=\"{ props, icon, textColorStyles, backgroundColorStyles, model }\" />\n  </template>\n</origam-selection-control>", "legend": [{"cls": ".origam-checkbox-btn", "num": 1, "descriptionKey": "components.checkbox_btn.anatomy.root", "descriptionFallback": "Root element. Hosts origam-selection-control and passes through computed classes and styles."}, {"cls": "origam-selection-control", "num": 2, "descriptionKey": "components.checkbox_btn.anatomy.selection_control", "descriptionFallback": "The underlying selection primitive. Manages model binding, focus, keyboard, ARIA and icon display."}, {"cls": "icon (via #input slot)", "num": 3, "descriptionKey": "components.checkbox_btn.anatomy.icon", "descriptionFallback": "Checkbox icon: falseIcon (unchecked) → trueIcon (checked) → indeterminateIcon (mixed). Swappable via the #input slot."}, {"cls": "label (via #label slot)", "num": 4, "descriptionKey": "components.checkbox_btn.anatomy.label", "descriptionFallback": "Label text area. Replaces the label prop when the #label slot is used."}], "classes": [{"cls": "origam-checkbox-btn", "descriptionKey": "components.checkbox_btn.anatomy.root", "descriptionFallback": "Root BEM class applied to the origam-selection-control element."}], "svgDesc": "Schematic of the CheckboxBtn component — delegates to origam-selection-control.", "svgTitle": "Anatomy of OrigamCheckboxBtn", "rootClass": "origam-checkbox-btn", "figcaption": "Anatomy of <code>&lt;origam-checkbox-btn&gt;</code> — 4 internal parts. The root ① carries a single <code>origam-selection-control</code> ② child which renders the icon ③ and label ④.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-checkbox-btn---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.checkbox_btn.css_vars.border_radius", "descriptionFallback": "Border radius of the button-checkbox container."}, {"name": "--origam-checkbox-btn---background-color", "defaultValue": "{color.action.secondary.bg}", "descriptionKey": "components.checkbox_btn.css_vars.background_color", "descriptionFallback": "Default background colour."}, {"name": "--origam-checkbox-btn---background-color-hover", "defaultValue": "{color.action.secondary.bgHover}", "descriptionKey": "components.checkbox_btn.css_vars.background_color_hover", "descriptionFallback": "Background colour on hover."}, {"name": "--origam-checkbox-btn---background-color-checked", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.checkbox_btn.css_vars.background_color_checked", "descriptionFallback": "Background colour when checked."}, {"name": "--origam-checkbox-btn---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.checkbox_btn.css_vars.color", "descriptionFallback": "Default foreground text colour."}, {"name": "--origam-checkbox-btn---color-checked", "defaultValue": "{color.text.onColor}", "descriptionKey": "components.checkbox_btn.css_vars.color_checked", "descriptionFallback": "Foreground colour when checked (on-primary surface)."}, {"name": "--origam-checkbox-btn---border-color", "defaultValue": "{color.border.default}", "descriptionKey": "components.checkbox_btn.css_vars.border_color", "descriptionFallback": "Default border colour."}, {"name": "--origam-checkbox-btn---border-color-checked", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.checkbox_btn.css_vars.border_color_checked", "descriptionFallback": "Border colour when checked."}, {"name": "--origam-checkbox-btn---font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.checkbox_btn.css_vars.font_size", "descriptionFallback": "Label font size."}, {"name": "--origam-checkbox-btn---opacity-disabled", "defaultValue": "{opacity.50}", "descriptionKey": "components.checkbox_btn.css_vars.opacity_disabled", "descriptionFallback": "Opacity when disabled."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.checkbox_btn.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.checkbox_btn.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed styles."}, {"name": "id", "type": "string", "descriptionKey": "components.checkbox_btn.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.checkbox_btn.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.checkbox_btn.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.checkbox_btn.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.checkbox_btn.playground.color", "defaultValue": "primary", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}, {"label": "compact", "value": "compact"}], "labelKey": "components.checkbox_btn.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.checkbox_btn.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "indeterminate", "labelKey": "components.checkbox_btn.playground.indeterminate", "defaultValue": false, "labelFallback": "Indeterminate"}], "defaultSlotContent": "Check me"}, "previewVariants": [{"label": "unchecked", "props": {"color": "primary"}, "slotContent": "Unchecked"}, {"label": "checked", "props": {"color": "primary", "modelValue": true}, "slotContent": "Checked"}, {"label": "indeterminate", "props": {"color": "primary", "indeterminate": true}, "slotContent": "Indeterminate"}, {"label": "disabled", "props": {"disabled": true}, "ariaLabel": "Disabled checkbox", "slotContent": "Disabled"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
