var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"44\" y=\"64.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"62\" y=\"64\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">Header — prepend / title / append</text>\n  <rect x=\"28\" y=\"92\" width=\"644\" height=\"58\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1\"/>\n  <circle cx=\"44\" cy=\"121\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"44\" y=\"125.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"62\" y=\"125\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">#default — Primary input field</text>\n  <rect x=\"28\" y=\"158\" width=\"644\" height=\"58\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1\"/>\n  <circle cx=\"44\" cy=\"187\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"44\" y=\"191.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"62\" y=\"191\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">#confirm — Confirmation input field</text>\n  <rect x=\"28\" y=\"224\" width=\"644\" height=\"28\" rx=\"4\" fill=\"none\"/>\n  <circle cx=\"44\" cy=\"238\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"242.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"62\" y=\"242\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">Details — messages / hint / counter</text>\n", "code": "<div class=\"origam-confirm-wrapper\">\n\n  <!-- header (conditional: prepend / title / append) -->\n  <div class=\"origam-confirm-wrapper__header\">\n    <div class=\"origam-confirm-wrapper__prepend\"><slot name=\"prepend\"/></div>\n    <div class=\"origam-confirm-wrapper__label\"><slot name=\"title\"/></div>\n    <div class=\"origam-confirm-wrapper__append\"><slot name=\"append\"/></div>\n  </div>\n\n  <!-- field row -->\n  <div class=\"origam-confirm-wrapper__content\">\n    <div class=\"origam-confirm-wrapper__field\">\n      <slot name=\"default\" />  <!-- primary input -->\n    </div>\n    <div class=\"origam-confirm-wrapper__confirm\">\n      <slot name=\"confirm\" />  <!-- confirmation input -->\n    </div>\n  </div>\n\n  <!-- details / messages -->\n  <div class=\"origam-confirm-wrapper__details\">\n    <slot name=\"messages\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-confirm-wrapper", "num": 1, "descriptionKey": "components.confirm_wrapper.anatomy.root", "descriptionFallback": "Root element. Manages shared validation state between the two inner inputs."}, {"cls": ".origam-confirm-wrapper__header", "num": 2, "descriptionKey": "components.confirm_wrapper.anatomy.header", "descriptionFallback": "Optional header row. Contains prepend, title and append sub-elements. Hidden when no header content is provided."}, {"cls": ".origam-confirm-wrapper__field", "num": 3, "descriptionKey": "components.confirm_wrapper.anatomy.field", "descriptionFallback": "Primary input container. The <code>#default</code> slot renders here."}, {"cls": ".origam-confirm-wrapper__confirm", "num": 4, "descriptionKey": "components.confirm_wrapper.anatomy.confirm", "descriptionFallback": "Confirmation input container. The <code>#confirm</code> slot renders here."}, {"cls": ".origam-confirm-wrapper__details", "num": 5, "descriptionKey": "components.confirm_wrapper.anatomy.details", "descriptionFallback": "Details row. Shows hint, messages and match-error text. Height governed by <code>--origam-confirm-wrapper---details-min-height</code>."}], "classes": [{"cls": "origam-confirm-wrapper", "descriptionKey": "components.confirm_wrapper.anatomy.root", "descriptionFallback": "Root container. Manages shared form validation."}, {"cls": "origam-confirm-wrapper__header", "descriptionKey": "components.confirm_wrapper.anatomy.header", "descriptionFallback": "Header row with prepend / label / append regions."}, {"cls": "origam-confirm-wrapper__prepend", "descriptionKey": "components.confirm_wrapper.anatomy.prepend", "descriptionFallback": "Leading icon/avatar area in the header."}, {"cls": "origam-confirm-wrapper__label", "descriptionKey": "components.confirm_wrapper.anatomy.label", "descriptionFallback": "Title area in the header."}, {"cls": "origam-confirm-wrapper__append", "descriptionKey": "components.confirm_wrapper.anatomy.append", "descriptionFallback": "Trailing icon/avatar area in the header."}, {"cls": "origam-confirm-wrapper__content", "descriptionKey": "components.confirm_wrapper.anatomy.content", "descriptionFallback": "Flex container holding both input slots (direction-aware: vertical / horizontal)."}, {"cls": "origam-confirm-wrapper__field", "descriptionKey": "components.confirm_wrapper.anatomy.field", "descriptionFallback": "Primary input slot wrapper."}, {"cls": "origam-confirm-wrapper__confirm", "descriptionKey": "components.confirm_wrapper.anatomy.confirm", "descriptionFallback": "Confirmation input slot wrapper."}, {"cls": "origam-confirm-wrapper__details", "descriptionKey": "components.confirm_wrapper.anatomy.details", "descriptionFallback": "Messages and hint area below the inputs."}], "svgDesc": "Schematic of the ConfirmWrapper component with numbered internal parts.", "svgTitle": "Anatomy of OrigamConfirmWrapper", "rootClass": "origam-confirm-wrapper", "figcaption": "Anatomy of <code>&lt;origam-confirm-wrapper&gt;</code> — 5 regions. The wrapper coordinates validation between the #default and #confirm slots, surfacing match errors in the details zone.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-confirm-wrapper---padding-start", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_start", "descriptionFallback": "Inline-start (left in LTR) padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-end", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_end", "descriptionFallback": "Inline-end (right in LTR) padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-top", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_top", "descriptionFallback": "Block-start padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-bottom", "defaultValue": "{space.4}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_bottom", "descriptionFallback": "Block-end padding of the wrapper."}, {"name": "--origam-confirm-wrapper---details-min-height", "defaultValue": "22px", "descriptionKey": "components.confirm_wrapper.css_vars.details_min_height", "descriptionFallback": "Minimum height of the details row to prevent layout shift when messages appear."}, {"name": "--origam-confirm-wrapper---horizontal-gap", "defaultValue": "1em", "descriptionKey": "components.confirm_wrapper.css_vars.horizontal_gap", "descriptionFallback": "Gap between primary and confirmation fields in horizontal direction mode."}, {"name": "--origam-confirm-wrapper--error---color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.confirm_wrapper.css_vars.error_color", "descriptionFallback": "Error text color rendered in the details row when values do not match."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.confirm_wrapper.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "validate", "type": "() => Promise<boolean>", "descriptionKey": "components.confirm_wrapper.exposed.validate", "descriptionFallback": "Triggers validation of both fields. Resolves to true when values match and all rules pass."}, {"name": "reset", "type": "() => void", "descriptionKey": "components.confirm_wrapper.exposed.reset", "descriptionFallback": "Resets both input values and clears validation state."}, {"name": "resetValidation", "type": "() => void", "descriptionKey": "components.confirm_wrapper.exposed.reset_validation", "descriptionFallback": "Clears validation messages without resetting values."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.confirm_wrapper.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.confirm_wrapper.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.confirm_wrapper.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.confirm_wrapper.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.confirm_wrapper.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "plain", "value": "plain"}, {"label": "underlined", "value": "underlined"}, {"label": "solo", "value": "solo"}], "labelKey": "components.confirm_wrapper.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.confirm_wrapper.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}, {"label": "compact", "value": "compact"}], "labelKey": "components.confirm_wrapper.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "select", "prop": "direction", "options": [{"label": "vertical", "value": "vertical"}, {"label": "horizontal", "value": "horizontal"}], "labelKey": "components.confirm_wrapper.playground.direction", "defaultValue": "vertical", "labelFallback": "Direction"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.confirm_wrapper.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "error", "labelKey": "components.confirm_wrapper.playground.error", "defaultValue": false, "labelFallback": "Error state"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('08688ff0-7639-45ea-b68c-93a1af500789', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'container', 'Container', 'Layout & Structure', NULL, 'mdi-page-layout-body', 'components.catalog.container.description', 'Page-level structural wrapper with responsive max-width breakpoints. Supports fluid and fullscreen modes.', NULL, NULL, 'origam-container', NULL, 'packages/ds/src/components/Grids/OrigamContainer.vue', 'origam', NULL, NULL, '/stories/?story=components-grids--design', '/docs/components/Grids/OrigamGrids.html', 'grids', '{"a11y": {"notes": [{"noteKey": "components.container.a11y.semantic", "noteFallback": "Container renders as <div> by default. Use the tag prop to set a semantic landmark element (e.g. <main>, <section>) when appropriate."}, {"noteKey": "components.container.a11y.rtl", "noteFallback": "Container applies RTL-aware classes via useRtl(). Padding and margin are expressed as logical properties (inline-start/end) so RTL layouts work without extra CSS."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"10\" y=\"15\" width=\"580\" height=\"90\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"60\" y=\"25\" width=\"480\" height=\"70\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"300\" y=\"65\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">max-width breakpoint zone</text>\n  <circle cx=\"68\" cy=\"33\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"37\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"77\" y1=\"33\" x2=\"160\" y2=\"12\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"164\" y=\"14\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-container</text>\n  <text x=\"18\" y=\"10\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">viewport</text>\n", "code": "<div class=\"origam-container\">\n  <!-- origam-container--fluid when fluid=true -->\n  <!-- origam-container--fullscreen when fullscreen=true -->\n  <slot name=\"default\" />\n</div>", "legend": [{"cls": ".origam-container", "num": 1, "descriptionKey": "components.container.anatomy.root", "descriptionFallback": "Root element (defaults to <code>&lt;div&gt;</code>). Applies horizontal auto margins and responsive max-width steps. Modifiers: <code>--fluid</code> (max-width: 100%), <code>--fullscreen</code> (100vh flex centred)."}], "classes": [{"cls": "origam-container", "descriptionKey": "components.container.anatomy.root", "descriptionFallback": "Base container class. Applies margin: auto and responsive max-width steps."}, {"cls": "origam-container--fluid", "descriptionKey": "components.container.anatomy.fluid", "descriptionFallback": "Removes the max-width constraint (100% width at all breakpoints)."}, {"cls": "origam-container--fullscreen", "descriptionKey": "components.container.anatomy.fullscreen", "descriptionFallback": "Forces 100% width and 100% height with flex centring."}], "svgDesc": "Schematic of Container with root wrapper and content slot.", "svgTitle": "Anatomy of OrigamContainer", "rootClass": "origam-container", "figcaption": "Anatomy of <code>&lt;origam-container&gt;</code> — 1 root element with responsive max-width and a default slot. The outer dashed rectangle represents the viewport.", "svgViewBox": "0 0 600 120"}, "cssVars": [{"name": "--origam-container---max-width", "defaultValue": "100%", "descriptionKey": "components.container.css_vars.max_width", "descriptionFallback": "Container max-width. Overridden per media breakpoint: 900px (md), 1200px (lg), 1800px (xl), 2400px (xxl)."}, {"name": "--origam-container---padding-inline-start", "defaultValue": "16px", "descriptionKey": "components.container.css_vars.padding_inline_start", "descriptionFallback": "Horizontal inner padding — start side."}, {"name": "--origam-container---padding-inline-end", "defaultValue": "16px", "descriptionKey": "components.container.css_vars.padding_inline_end", "descriptionFallback": "Horizontal inner padding — end side."}, {"name": "--origam-container---margin-inline-start", "defaultValue": "auto", "descriptionKey": "components.container.css_vars.margin_inline_start", "descriptionFallback": "Left auto margin (centres the container horizontally)."}, {"name": "--origam-container---margin-inline-end", "defaultValue": "auto", "descriptionKey": "components.container.css_vars.margin_inline_end", "descriptionFallback": "Right auto margin (centres the container horizontally)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.container.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.container.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.container.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.container.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.container.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.container.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "fluid", "labelKey": "components.container.playground.fluid", "defaultValue": false, "labelFallback": "Fluid"}, {"kind": "switch", "prop": "fullscreen", "labelKey": "components.container.playground.fullscreen", "defaultValue": false, "labelFallback": "Fullscreen"}], "defaultSlotContent": "Content"}, "previewVariants": [{"label": "default", "props": {}, "slotContent": "Container content"}, {"label": "fluid", "props": {"fluid": true}, "slotContent": "Fluid container"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7a30be3d-97f7-414e-9f3c-8f019a1140e3', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'contextual-menu', 'ContextualMenu', 'Navigation', NULL, 'mdi-menu', 'components.catalog.contextual_menu.description', 'Right-click context menu that opens at the cursor position. Wraps OrigamMenu with openOnContextMenu + target="cursor" + activator="cursor" preconfigured.', NULL, NULL, 'origam-contextual-menu', NULL, 'packages/ds/src/components/ContextualMenu/OrigamContextualMenu.vue', 'origam', NULL, NULL, '/stories/?story=components-contextualmenu--design', '/docs/components/ContextualMenu/OrigamContextualMenu.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.contextual_menu.a11y.cursor_note", "noteFallback": "The menu panel is positioned at the exact cursor coordinates of the right-click event via target=\"cursor\". This matches the native browser context menu behaviour."}, {"noteKey": "components.contextual_menu.a11y.focus_note", "noteFallback": "On open, focus moves to the first enabled menu item. On close (Escape), focus returns to the element that received the right-click."}], "roles": ["menu", "menuitem"], "keyboard": [{"key": "Escape", "actionKey": "components.contextual_menu.a11y.key_escape", "actionFallback": "Closes the context menu and returns focus to the trigger element."}, {"key": "↑ / ↓", "actionKey": "components.contextual_menu.a11y.key_navigate", "actionFallback": "Navigate between menu items."}, {"key": "Enter / Space", "actionKey": "components.contextual_menu.a11y.key_select", "actionFallback": "Activates the focused menu item."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #f5f5f5)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"230\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fafafa)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"135\" font-size=\"13\" fill=\"var(--origam-color__text---disabled, #bbb)\" text-anchor=\"middle\" font-family=\"system-ui\">Right-click zone (#activator)</text>\n  <circle cx=\"36\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"200\" y=\"160\" width=\"220\" height=\"120\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.12))\" stroke-width=\"1.5\" filter=\"url(#shadow)\"/>\n  <circle cx=\"216\" cy=\"168\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"216\" y=\"172.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"208\" y=\"180\" width=\"204\" height=\"32\" rx=\"4\" fill=\"var(--origam-color__action--secondary---bg, rgba(124,58,237,0.08))\"/>\n  <text x=\"220\" y=\"200\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Cut</text>\n  <rect x=\"208\" y=\"214\" width=\"204\" height=\"32\" rx=\"4\" fill=\"none\"/>\n  <text x=\"220\" y=\"234\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Copy</text>\n  <rect x=\"208\" y=\"248\" width=\"204\" height=\"28\" rx=\"4\" fill=\"none\"/>\n  <text x=\"220\" y=\"266\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">Paste</text>\n  <circle cx=\"216\" cy=\"200\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"216\" y=\"204.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"290\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b0b0b0)\" text-anchor=\"middle\" font-style=\"italic\">① = activator zone (v-bind=\"props\"). ② = menu panel (role=\"menu\"). ③ = menu items (#default slot).</text>\n", "code": "<!-- OrigamContextualMenu wraps OrigamMenu with preconfigured open-on-context-menu -->\n<!-- All OrigamMenu slots are forwarded transparently -->\n<origam-menu\n  open-on-context-menu\n  target=\"cursor\"\n  activator=\"cursor\"\n>\n  <!-- #default slot: your menu content -->\n  <origam-list>\n    <origam-list-item title=\"Cut\"   prepend-icon=\"mdi-content-cut\" />\n    <origam-list-item title=\"Copy\"  prepend-icon=\"mdi-content-copy\" />\n    <origam-list-item title=\"Paste\" prepend-icon=\"mdi-content-paste\" />\n  </origam-list>\n\n  <!-- #activator slot: the right-click zone -->\n  <template #activator=\"{ props }\">\n    <div v-bind=\"props\">Right-click zone</div>\n  </template>\n</origam-menu>", "legend": [{"cls": "activator zone", "num": 1, "descriptionKey": "components.contextual_menu.anatomy.activator", "descriptionFallback": "The element or region that captures the <code>contextmenu</code> event. Defined via the <code>#activator</code> slot or the parent element when no activator is provided."}, {"cls": ".origam-contextual-menu (OrigamMenu root)", "num": 2, "descriptionKey": "components.contextual_menu.anatomy.menu_panel", "descriptionFallback": "Floating menu panel positioned at the cursor via <code>target=\"cursor\"</code>. Background and box-shadow come from contextual-menu tokens. Position is <code>fixed</code> relative to the viewport."}, {"cls": "#default slot", "num": 3, "descriptionKey": "components.contextual_menu.anatomy.content", "descriptionFallback": "Menu content — typically an <code>&lt;origam-list&gt;</code> with <code>&lt;origam-list-item&gt;</code> elements. Max-width is constrained by <code>--origam-contextual-menu__content---max-width</code>."}], "classes": [{"cls": "origam-contextual-menu", "descriptionKey": "components.contextual_menu.anatomy.root", "descriptionFallback": "Root element — thin wrapper over OrigamMenu. Inherits all Menu BEM classes."}], "svgDesc": "Schematic of the ContextualMenu component with numbered regions.", "svgTitle": "Anatomy of OrigamContextualMenu", "rootClass": "origam-contextual-menu", "figcaption": "Anatomy of <code>&lt;origam-contextual-menu&gt;</code>. The component wraps <code>OrigamMenu</code> with <code>openOnContextMenu</code> + <code>target=\"cursor\"</code> pre-configured. Menu panel positions at the exact cursor coordinates of the right-click.", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-contextual-menu---background", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.contextual_menu.css_vars.background", "descriptionFallback": "Background color of the menu panel."}, {"name": "--origam-contextual-menu---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.contextual_menu.css_vars.color", "descriptionFallback": "Foreground color of the menu panel."}, {"name": "--origam-contextual-menu---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.contextual_menu.css_vars.border_radius", "descriptionFallback": "Border-radius of the menu panel."}, {"name": "--origam-contextual-menu---box-shadow", "defaultValue": "{shadow.lg}", "descriptionKey": "components.contextual_menu.css_vars.box_shadow", "descriptionFallback": "Box shadow (elevation) of the menu panel."}, {"name": "--origam-contextual-menu---z-index", "defaultValue": "{zIndex.dropdown} → 1000", "descriptionKey": "components.contextual_menu.css_vars.z_index", "descriptionFallback": "Z-index of the menu panel. Appears above content but below modal-level surfaces."}, {"name": "--origam-contextual-menu__content---max-width", "defaultValue": "320px", "descriptionKey": "components.contextual_menu.css_vars.content_max_width", "descriptionFallback": "Maximum width of the menu content area."}, {"name": "--origam-contextual-menu---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.contextual_menu.css_vars.transition_duration", "descriptionFallback": "Open/close transition duration."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.contextual_menu.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the underlying OrigamMenu."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.contextual_menu.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.contextual_menu.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.contextual_menu.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.contextual_menu.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.contextual_menu.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "modelValue", "labelKey": "components.contextual_menu.playground.model_value", "defaultValue": false, "labelFallback": "Open"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.contextual_menu.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.contextual_menu.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(default)", "value": ""}, {"label": "none", "value": "none"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.contextual_menu.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2998a8da-e9dd-4e6a-8eab-3edd43b535cf', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'counter', 'Counter', 'Data Display', NULL, 'mdi-counter', 'components.catalog.counter.description', 'Animated character-count badge that shows current/max values. Used internally by TextField, Textarea and similar inputs.', NULL, NULL, 'origam-counter', NULL, 'packages/ds/src/components/Counter/OrigamCounter.vue', 'origam', NULL, NULL, '/stories/?story=components-counter--design', '/docs/components/Counter/OrigamCounter.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.counter.a11y.aria_note", "noteFallback": "OrigamCounter is a visual helper only. When embedded in a text field, the parent field should use aria-describedby pointing to the counter element so screen readers announce the character count."}, {"noteKey": "components.counter.a11y.live_note", "noteFallback": "For dynamic character-count announcements, add aria-live=\"polite\" to the counter element or its parent container."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-counter---color", "descriptionKey": "components.counter.tokens.color", "descriptionFallback": "Default text colour."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-counter---color-active", "descriptionKey": "components.counter.tokens.color_active", "descriptionFallback": "Text colour when field is active/focused."}, {"type": "color", "value": "var(--origam-color__feedback--danger---fgSubtle)", "tokenPath": "--origam-counter---color-error", "descriptionKey": "components.counter.tokens.color_error", "descriptionFallback": "Text colour when value exceeds max."}, {"type": "dimension", "value": "var(--origam-font__size---xs)", "tokenPath": "--origam-counter---font-size", "descriptionKey": "components.counter.tokens.font_size", "descriptionFallback": "Counter font size."}, {"type": "number", "value": "var(--origam-opacity---70)", "tokenPath": "--origam-counter---opacity", "descriptionKey": "components.counter.tokens.opacity", "descriptionFallback": "Default counter opacity."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fdf4ff)\" rx=\"4\"/>\n  <origam-transition name=\"origam-slide-y-transition\">\n    <rect x=\"280\" y=\"50\" width=\"140\" height=\"36\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1.5\"/>\n  </origam-transition>\n  <text x=\"350\" y=\"73\" font-size=\"13\" fill=\"var(--origam-color__text---secondary, #666)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">12 / 50</text>\n  <circle cx=\"296\" cy=\"58\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"296\" y=\"62.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"350\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"62.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"296\" y1=\"46\" x2=\"296\" y2=\"28\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.4))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"180\" y=\"26\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #7e5fb0)\" font-style=\"italic\" text-anchor=\"middle\">origam-counter (root tag)</text>\n  <line x1=\"350\" y1=\"46\" x2=\"350\" y2=\"28\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"510\" y=\"26\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #7e5fb0)\" font-style=\"italic\" text-anchor=\"middle\">#default slot — renders \"value / max\"</text>\n  <text x=\"350\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Wrapped in OrigamTransition (slide-y). --error modifier when value &gt; max.</text>\n", "code": "<!-- Wrapped in OrigamTransition for animated show/hide -->\n<origam-transition :transition=\"transition\">\n  <component\n    :is=\"tag\"\n    v-show=\"active\"\n    class=\"origam-counter\"\n    :class=\"{ ''origam-counter--error'': value > max && !disabled }\"\n  >\n    <!-- #default slot: { counter, max, value } -->\n    <slot :counter=\"counter\" :max=\"max\" :value=\"value\">\n      {{ counter }}\n    </slot>\n  </component>\n</origam-transition>", "legend": [{"cls": ".origam-counter", "num": 1, "descriptionKey": "components.counter.anatomy.root", "descriptionFallback": "Root element. Tag is controlled by the <code>tag</code> prop (default: <code>div</code>). Wrapped in <code>&lt;origam-transition&gt;</code> for animated show/hide. Modifier <code>--error</code> applied when <code>value &gt; max</code>."}, {"cls": "#default slot", "num": 2, "descriptionKey": "components.counter.anatomy.slot", "descriptionFallback": "Counter content. Default renderer produces \"<code>value / max</code>\" when max is set, or just \"<code>value</code>\" otherwise. Slot props: <code>{ counter, max, value }</code>."}], "classes": [{"cls": "origam-counter", "descriptionKey": "components.counter.anatomy.root", "descriptionFallback": "Root element. Transition-wrapped, v-show controlled by active prop."}, {"cls": "origam-counter--error", "descriptionKey": "components.counter.anatomy.error", "descriptionFallback": "Applied when value > max and disabled is false. Switches text colour to the danger token."}], "svgDesc": "Schematic of the Counter component with numbered parts.", "svgTitle": "Anatomy of OrigamCounter", "rootClass": "origam-counter", "figcaption": "Anatomy of <code>&lt;origam-counter&gt;</code>. A single root element (① tag) wraps the default slot (②) which renders the computed \"<code>value / max</code>\" string. The <code>--error</code> modifier is applied when <code>value &gt; max</code>.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-counter---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.counter.css_vars.color", "descriptionFallback": "Default counter text colour."}, {"name": "--origam-counter---color-active", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.counter.css_vars.color_active", "descriptionFallback": "Counter text colour when the field is focused / active."}, {"name": "--origam-counter---color-error", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.counter.css_vars.color_error", "descriptionFallback": "Counter text colour when value exceeds max (--error modifier)."}, {"name": "--origam-counter---font-size", "defaultValue": "{font.size.xs}", "descriptionKey": "components.counter.css_vars.font_size", "descriptionFallback": "Counter font size."}, {"name": "--origam-counter---font-weight", "defaultValue": "{font.weight.regular}", "descriptionKey": "components.counter.css_vars.font_weight", "descriptionFallback": "Counter font weight."}, {"name": "--origam-counter---opacity", "defaultValue": "{opacity.70}", "descriptionKey": "components.counter.css_vars.opacity", "descriptionFallback": "Default opacity. Set to 1 when active/focused."}, {"name": "--origam-counter---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.counter.css_vars.transition_duration", "descriptionFallback": "Transition duration for colour/opacity changes."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.counter.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.counter.exposed.css", "descriptionFallback": "Reactive CSS string for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.counter.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.counter.exposed.load", "descriptionFallback": "Injects the style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.counter.exposed.unload", "descriptionFallback": "Removes the style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.counter.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "number", "prop": "value", "labelKey": "components.counter.playground.value", "defaultValue": 12, "labelFallback": "Value"}, {"kind": "number", "prop": "max", "labelKey": "components.counter.playground.max", "defaultValue": 50, "labelFallback": "Max"}, {"kind": "switch", "prop": "active", "labelKey": "components.counter.playground.active", "defaultValue": true, "labelFallback": "Active (visible)"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.counter.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.counter.playground.color", "defaultValue": "", "labelFallback": "Color"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
