INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9d93fd9e-1a51-4bff-8466-2a081f9e2fcd', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'data-table', 'DataTable', 'Data Display', NULL, 'mdi-table', 'components.catalog.data_table.description', 'Feature-rich data table with sorting, multi-sort, grouping, row selection, column pinning, virtual pagination and full slot customisation.', NULL, NULL, 'origam-data-table', NULL, 'packages/ds/src/components/DataTable/OrigamDataTable.vue', 'origam', NULL, NULL, '/stories/?story=components-datatable--design', '/docs/components/DataTable/OrigamDataTable.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.data_table.a11y.table_note", "noteFallback": "The table renders as a semantic <table> with proper <thead>, <tbody>, <tr>, <th> (scope=\"col\") and <td>. Screen readers can announce the table structure natively."}, {"noteKey": "components.data_table.a11y.sort_note", "noteFallback": "Sortable header cells use aria-sort=\"ascending\" | \"descending\" | \"none\". Sort direction changes are announced by screen readers without additional ARIA live regions."}, {"noteKey": "components.data_table.a11y.select_note", "noteFallback": "Row checkboxes have aria-label describing the row (e.g. \"Select row Alice Martin\"). The select-all checkbox uses aria-label=\"Select all\"."}], "roles": ["table", "rowheader", "columnheader", "row", "cell"], "keyboard": [{"key": "Tab", "actionKey": "components.data_table.a11y.key_tab", "actionFallback": "Move focus between header sort buttons, checkboxes and pagination controls."}, {"key": "Enter / Space", "actionKey": "component