INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('870abf69-69da-4b19-8374-2faa4222e8b7', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'data-table-footer', 'DataTableFooter', 'Data Display', NULL, 'mdi-table-row', 'components.catalog.data_table_footer.description', 'Pagination and items-per-page footer bar rendered below the DataTable body.', NULL, NULL, 'origam-data-table-footer', NULL, 'packages/ds/src/components/DataTable/OrigamDataTableFooter.vue', 'origam', NULL, NULL, '/stories/?story=components-datatable--design', '/docs/components/DataTable/OrigamDataTable.html', 'data-table', '{"a11y": {"notes": [{"noteKey": "components.data_table_footer.a11y.pagination_note", "noteFallback": "The embedded OrigamPagination provides aria-label attributes on first/prev/next/last buttons via firstPageLabel, prevPageLabel, nextPageLabel and lastPageLabel props."}], "roles": ["contentinfo"], "keyboard": [{"key": "Tab", "actionKey": "components.data_table_footer.a11y.key_tab", "actionFallback": "Moves focus through the items-per-page select and pagination buttons."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"10\" y=\"20\" width=\"680\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---default, #fff)\" stroke=\"var(--origam-color__border---default, #e5d9f9)\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"40\" width=\"160\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #f5f0ff)\" stroke=\"var(--origam-color__border---default, #c4b0f0)\" stroke-width=\"1\"/>\n  <tex