"year\" />\n\n    <!-- OR view: months -->\n    <origam-date-picker-months v-model:month=\"month\" :year=\"year\" />\n\n    <!-- OR view: years -->\n    <origam-date-picker-years v-model:year=\"year\" />\n  </origam-fade>\n\n  <!-- slot: #actions -->\n  <template #actions>\n    <origam-btn text=\"Cancel\" variant=\"text\" />\n    <origam-btn text=\"OK\" color=\"primary\" />\n  </template>\n</origam-picker>", "legend": [{"cls": ".origam-date-picker", "num": 1, "descriptionKey": "components.date_picker.anatomy.root", "descriptionFallback": "Root element. Fixed width 328px (368px with showWeek). Built on OrigamPicker with overflow:hidden. Modifier --year / --months applied while switching view."}, {"cls": "OrigamDatePickerHeader", "num": 2, "descriptionKey": "components.date_picker.anatomy.header", "descriptionFallback": "Coloured header strip (background from header.background-color token = color.action.primary.bg). Shows the selected date. Hidden via hideHeader prop. Replaced by the #header slot."}, {"cls": "OrigamDatePickerControls", "num": 3, "descriptionKey": "components.date_picker.anatomy.controls", "descriptionFallback": "Navigation bar with prev/next arrow buttons and a text button that toggles between month, months and year views."}, {"cls": "OrigamDatePickerMonth", "num": 4, "descriptionKey": "components.date_picker.anatomy.month", "descriptionFallback": "Day-grid view. Weekday labels row + 6 rows of day buttons. Day cells use day.size (40px) and day.border-radius (full). Animated via OrigamFade when switching views."}, {"cls": "#actions slot", "num": 5, "descriptionKey": "components.date_picker.anatomy.actions", "descriptionFallback": "Optional action buttons row. Use for Cancel / OK confirmation pattern. Only rendered when the #actions slot is provided."}], "classes": [{"cls": "origam-date-picker", "descriptionKey": "components.date_picker.anatomy.root", "descriptionFallback": "Root picker element."}, {"cls": "origam-date-picker--month", "descriptionKey": 