OnEscape", "labelKey": "components.inline_edit.playground.cancel_on_escape", "defaultValue": true, "labelFallback": "Cancel On Escape"}, {"kind": "switch", "prop": "multiline", "labelKey": "components.inline_edit.playground.multiline", "defaultValue": false, "labelFallback": "Multiline"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('aeb63c78-69b8-4ac1-94c0-7b64c5efeaa4', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'input', 'Input', 'Form & Input', NULL, 'mdi-form-textbox', 'components.catalog.input.description', 'Base input wrapper that provides validation, labels, hints, adjacent slots and focus management. Consumed internally by all typed input components.', NULL, NULL, 'origam-input', NULL, 'packages/ds/src/components/Input/OrigamInput.vue', 'origam', NULL, NULL, '/stories/?story=components-input--design', '/docs/components/Input/OrigamInput.html', NULL, '{"playground": {"controls": [{"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.input.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.input.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.input.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}, {"kind": "text", "prop": "label", "labelKey": "components.input.playground.label", "defaultValue": "", "labelFallback": "Label"}, {"kind": "switch", "prop": "centerAffix", "labelKey": "components.input.playground.center_affix", "defaultValue": false, "labelFallback": "Center Affix"}, {"kind": "switch", "prop": "hideSpinButtons", "labelKey": "components.input.playground.hide_spin_buttons",