INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c0623ce8-2bc1-40f1-a9a6-03152d5836cf', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'progress', 'Progress', 'Feedback & Status', NULL, 'mdi-progress-clock', 'components.catalog.progress.description', 'Progress indicator family: linear bar (determinate, indeterminate, buffered, stream, striped, clickable) and circular spinner (determinate, indeterminate, rotate). Dispatched via the type prop.', NULL, NULL, 'origam-progress', NULL, 'packages/ds/src/components/Progress/OrigamProgress.vue', 'origam', NULL, NULL, '/stories/?story=components-progress--design', '/docs/components/Progress/OrigamProgress.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.progress.a11y.role_note", "noteFallback": "Both ProgressLinear and ProgressCircular have role=\"progressbar\". They bind aria-valuemin=\"0\", aria-valuemax, and aria-valuenow (undefined in indeterminate mode). aria-label comes from the label prop (defaults to \"Loading\")."}, {"noteKey": "components.progress.a11y.hidden_note", "noteFallback": "When active=false, the component sets aria-hidden=\"true\" to remove it from the accessibility tree without removing it from the DOM."}, {"noteKey": "components.progress.a11y.reduced_motion", "noteFallback": "Indeterminate animations are paused under prefers-reduced-motion: reduce."}], "roles": ["progressbar"], "keyboard": []}, "tokens": {"excerpt": [{"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-progress-linear---transition-duration", "descriptionKey": "components.progress.tokens.linear_transition", "descriptionFallback": "Linear fill bar transition duration."}, {"type": "duration", "value": "2200ms", "tokenPath": "--origam-progress-linear---indeterminate-duration", "descriptionKey": "components.progress.tokens.linear_indeterminate", "descriptionFallback": "Indeterminate animation duration for the linear bar."}, {"type": "dimension", "value": "32px", "tokenPath": "--origam-progress-circular---size-md", "descriptionKey": "components.progress.tokens.circular_size_md", "descriptionFallback": "Default (medium) circular spinner size."}, {"type": "duration", "value": "1400ms", "tokenPath": "--origam-progress-circular---indeterminate-duration", "descriptionKey": "components.progress.tokens.circular_indeterminate", "descriptionFallback": "Spin animation duration for the indeterminate circular variant."}, {"type": "number", "value": "var(--origam-opacity---50)", "tokenPath": "--origam-progress-circular__underlay---opacity", "descriptionKey": "components.progress.tokens.circular_underlay_opacity", "descriptionFallback": "Opacity of the background ring."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"30\" y=\"30\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" font-weight=\"600\" font-family=\"''JetBrains Mono'',monospace\">ProgressLinear</text>\n  <rect x=\"30\" y=\"40\" width=\"620\" height=\"24\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.12))\"/>\n  <rect x=\"30\" y=\"40\" width=\"372\" height=\"24\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.85\"/>\n  <rect x=\"620\" y=\"36\" width=\"80\" height=\"32\" rx=\"2\" fill=\"transparent\"/>\n  <text x=\"660\" y=\"56\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot</text>\n  <rect x=\"30\" y=\"72\" width=\"620\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, rgba(124,58,237,0.12))\"/>\n  <rect x=\"30\" y=\"72\" width=\"248\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__feedback--info---bg, rgba(8,145,178,0.5))\"/>\n  <text x=\"360\" y=\"90\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">buffer track</text>\n  <text x=\"30\" y=\"115\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" font-weight=\"600\" font-family=\"''JetBrains Mono'',monospace\">ProgressCircular</text>\n  <circle cx=\"120\" cy=\"175\" r=\"50\" fill=\"transparent\" stroke=\"var(--origam-color__surface---disabled, rgba(124,58,237,0.15))\" stroke-width=\"8\"/>\n  <circle cx=\"120\" cy=\"175\" r=\"50\" fill=\"transparent\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"8\" stroke-dasharray=\"314\" stroke-dashoffset=\"80\" transform=\"rotate(-90 120 175)\"/>\n  <text x=\"120\" y=\"180\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #111)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">75%</text>\n  <circle cx=\"290\" cy=\"175\" r=\"50\" fill=\"transparent\" stroke=\"var(--origam-color__surface---disabled, rgba(124,58,237,0.15))\" stroke-width=\"8\"/>\n  <circle cx=\"290\" cy=\"175\" r=\"50\" fill=\"transparent\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"8\" stroke-dasharray=\"314\" stroke-dashoffset=\"0\" opacity=\"0.5\" transform=\"rotate(-90 290 175)\"/>\n  <text x=\"290\" y=\"180\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">indeterminate</text>\n  <circle cx=\"26\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"48\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"26\" cy=\"76\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"80\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"66\" cy=\"175\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"66\" y=\"179\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"66\" cy=\"145\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"66\" y=\"149\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"120\" cy=\"124\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"120\" y=\"128\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<!-- Linear -->\n<div class=\"origam-progress-linear\" role=\"progressbar\" :aria-valuenow=\"value\">\n  <div class=\"origam-progress__stream\"/>\n  <div class=\"origam-progress__background-track\"/>\n  <div class=\"origam-progress__bar\"/>            <!-- determinate -->\n  <div class=\"origam-progress__bar--long\"/>      <!-- indeterminate -->\n  <div class=\"origam-progress__bar--short\"/>     <!-- indeterminate -->\n  <div class=\"origam-progress__content\">\n    <slot :value=\"normalizedValue\" :buffer=\"normalizedBuffer\"/>\n  </div>\n</div>\n\n<!-- Circular -->\n<div class=\"origam-progress-circular\" role=\"progressbar\" :aria-valuenow=\"value\">\n  <svg :viewBox=\"svgViewBox\">\n    <circle class=\"origam-progress__underlay\"/>  <!-- background ring -->\n    <circle class=\"origam-progress__overlay\"/>   <!-- fill arc -->\n  </svg>\n  <div class=\"origam-progress__content\">\n    <slot :value=\"normalizedValue\"/>\n  </div>\n</div>", "legend": [{"cls": ".origam-progress__bar", "num": 1, "descriptionKey": "components.progress.anatomy.bar", "descriptionFallback": "Linear: foreground fill bar. Width = normalized value %. In indeterminate mode, two bars (--long and --short) animate in loop."}, {"cls": ".origam-progress__stream / background track", "num": 2, "descriptionKey": "components.progress.anatomy.background", "descriptionFallback": "Linear: background track (opacity 50% of fill color) and optional stream dots. Buffer renders a secondary transparent track at bufferValue."}, {"cls": "SVG underlay circle", "num": 3, "descriptionKey": "components.progress.anatomy.circular_underlay", "descriptionFallback": "Circular: background ring (stroke = {color.surface.disabled}, opacity 50%). Always visible."}, {"cls": "SVG overlay circle", "num": 4, "descriptionKey": "components.progress.anatomy.circular_overlay", "descriptionFallback": "Circular: foreground arc. stroke-dashoffset driven by normalized value. Animated by CSS in indeterminate mode."}, {"cls": ".origam-progress__content", "num": 5, "descriptionKey": "components.progress.anatomy.content", "descriptionFallback": "Shared content zone. Circular: absolutely centered inside the ring. Linear: overlaid on the bar. Visible only when #default slot has content."}], "classes": [{"cls": "origam-progress-linear", "descriptionKey": "components.progress.anatomy.linear_root", "descriptionFallback": "Root element for the linear variant."}, {"cls": "origam-progress__bar", "descriptionKey": "components.progress.anatomy.bar", "descriptionFallback": "Foreground fill bar (determinate) or animated long/short bars (indeterminate)."}, {"cls": "origam-progress__bar--long", "descriptionKey": "components.progress.anatomy.bar_long", "descriptionFallback": "Indeterminate: long primary bar."}, {"cls": "origam-progress__bar--short", "descriptionKey": "components.progress.anatomy.bar_short", "descriptionFallback": "Indeterminate: short secondary bar."}, {"cls": "origam-progress__stream", "descriptionKey": "components.progress.anatomy.stream", "descriptionFallback": "Stream dots animation element. Only present when stream=true."}, {"cls": "origam-progress-circular", "descriptionKey": "components.progress.anatomy.circular_root", "descriptionFallback": "Root element for the circular variant."}, {"cls": "origam-progress__content", "descriptionKey": "components.progress.anatomy.content", "descriptionFallback": "Content slot overlay. Centered absolutely over the indicator."}], "svgDesc": "Schematic of the ProgressLinear and ProgressCircular components with numbered parts.", "svgTitle": "Anatomy of OrigamProgress", "rootClass": "origam-progress-linear", "figcaption": "Anatomy of <code>&lt;origam-progress&gt;</code> — Linear: fill bar (①) + buffer track (②). Circular: SVG underlay ring (③) + overlay arc (④) + content slot (⑤).", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-progress-linear---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.progress.css_vars.linear_transition", "descriptionFallback": "Transition duration for the fill bar width change."}, {"name": "--origam-progress-linear---indeterminate-duration", "defaultValue": "2200ms", "descriptionKey": "components.progress.css_vars.linear_indeterminate", "descriptionFallback": "Duration of the indeterminate bar animation cycle."}, {"name": "--origam-progress-linear---rounded-border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.progress.css_vars.linear_rounded", "descriptionFallback": "Border-radius applied when rounded=true."}, {"name": "--origam-progress-circular---size-xs", "defaultValue": "16px", "descriptionKey": "components.progress.css_vars.circular_size_xs", "descriptionFallback": "Circular size for size=\"x-small\"."}, {"name": "--origam-progress-circular---size-xl", "defaultValue": "64px", "descriptionKey": "components.progress.css_vars.circular_size_xl", "descriptionFallback": "Circular size for size=\"x-large\"."}, {"name": "--origam-progress-circular---indeterminate-duration", "defaultValue": "1400ms", "descriptionKey": "components.progress.css_vars.circular_indeterminate", "descriptionFallback": "Duration of the indeterminate circular spin animation."}, {"name": "--origam-progress-circular__underlay---color", "defaultValue": "{color.surface.disabled}", "descriptionKey": "components.progress.css_vars.circular_underlay_color", "descriptionFallback": "Color of the background ring (underlay circle)."}], "playground": {"controls": [{"kind": "select", "prop": "type", "options": [{"label": "linear", "value": "linear"}, {"label": "circular", "value": "circular"}], "labelKey": "components.progress.playground.type", "defaultValue": "linear", "labelFallback": "Type"}, {"kind": "number", "prop": "modelValue", "labelKey": "components.progress.playground.model_value", "defaultValue": 60, "labelFallback": "Value"}, {"kind": "switch", "prop": "indeterminate", "labelKey": "components.progress.playground.indeterminate", "defaultValue": false, "labelFallback": "Indeterminate"}, {"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.progress.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "striped", "labelKey": "components.progress.playground.striped", "defaultValue": false, "labelFallback": "Striped (linear)"}, {"kind": "switch", "prop": "rounded", "labelKey": "components.progress.playground.rounded", "defaultValue": false, "labelFallback": "Rounded (linear)"}, {"kind": "select", "prop": "size", "options": [{"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.progress.playground.size", "defaultValue": "default", "labelFallback": "Size (circular)"}]}, "previewVariants": [{"label": "linear default", "props": {"color": "primary", "modelValue": 60}}, {"label": "linear indeterminate", "props": {"color": "primary", "indeterminate": true}}, {"label": "linear striped", "props": {"color": "success", "striped": true, "modelValue": 45}}, {"label": "circular", "props": {"type": "circular", "color": "primary", "modelValue": 75}}, {"label": "circular indeterminate", "props": {"type": "circular", "color": "danger", "indeterminate": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
