xt-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<origam-sheet class=\"origam-picker\">\n  <!-- title strip (always shown unless hideHeader=true) -->\n  <div class=\"origam-picker__title\">\n    <slot name=\"title\">\n      <origam-picker-title :title=\"title\" :color=\"color\" :bg-color=\"bgColor\" />\n    </slot>\n  </div>\n\n  <!-- optional header (navigation arrows, tabs…) -->\n  <div v-if=\"slots.header\" class=\"origam-picker__header\">\n    <slot name=\"header\"/>\n  </div>\n\n  <!-- body: date grid / color wheel / custom content -->\n  <div class=\"origam-picker__body\">\n    <slot name=\"default\"/>\n  </div>\n\n  <!-- optional actions footer -->\n  <div v-if=\"slots.actions\" class=\"origam-picker__actions\">\n    <slot name=\"actions\"/>\n  </div>\n</origam-sheet>", "legend": [{"cls": ".origam-picker__title", "num": 1, "descriptionKey": "components.picker.anatomy.title", "descriptionFallback": "OrigamPickerTitle strip at the top. Hosts the #title slot or the title prop text. Themed via color and bgColor."}, {"cls": ".origam-picker__header", "num": 2, "descriptionKey": "components.picker.anatomy.header", "descriptionFallback": "Optional header zone between the title and the body. Only rendered when the #header slot has content."}, {"cls": ".origam-picker__body", "num": 3, "descriptionKey": "components.picker.anatomy.body", "descriptionFallback": "Main body area. Hosts the #default slot content (calendar grid, color wheel, etc.)."}, {"cls": ".origam-picker__actions", "num": 4, "descriptionKey": "components.picker.anatomy.actions", "descriptionFallback": "Footer zone for action buttons (Cancel / OK). Only rendered when the #actions slot has content."}, {"cls": ".origam-picker", "num": 5, "descriptionKey": "components.picker.anatomy.root", "descriptionFallback": "Root OrigamSheet panel. Applies border, rounded, elevation, min-width and width from props and tokens."}], "classes": [{"cls": "origam-picker", "descriptionKey": "components.picker.anatomy.root", "descriptionFallback": "Root sheet container. Applies min-width, border-radius, box-shadow from tokens."}, {"cls": "origam-picker__title", "descriptionKey": "components.picker.anatomy.title", "descriptionFallback": "Title zone wrapper rendered at the top of the panel."}, {"cls": "origam-picker__header", "descriptionKey": "components.picker.anatomy.header", "descriptionFallback": "Optional header slot between title and body."}, {"cls": "origam-picker__body", "descriptionKey": "components.picker.anatomy.body", "descriptionFallback": "Main body slot container."}, {"cls": "origam-picker__actions", "descriptionKey": "components.picker.anatomy.actions", "descriptionFallback": "Optional footer actions zone."}], "svgDesc": "Schematic of the Picker component with 5 numbered zones.", "svgTitle": "Anatomy of OrigamPicker", "rootClass": "origam-picker", "figcaption": "Anatomy of <code>&lt;origam-picker&gt;</code> — 5 zones: title strip (PickerTitle), optional header slot, body (#default slot), actions footer, and the root sheet container.", "svgViewBox": "0 0 700 320"}, "cssVars": [{"name": "--origam-picker---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.picker.css_vars.background_color", "descriptionFallback": "Picker panel background color."}, {"name": "--origam-picker---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.picker.css_vars.color", "descriptionFallback": "Picker panel text color."}, {"name": "--origam-picker---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.picker.css_vars.border_radius", "descriptionFallback": "Border-radius of the panel."}, {"name": "--origam-picker---box-shadow", "defaultValue": "{shadow.lg}", "descriptionKey": "components.picker.css_vars.box_shadow", "descriptionFallback": "Drop shadow of the panel."}, {"name": "--origam-picker---min-width", "defaultValue": "320px", "descriptionKey": "components.picker.css_vars.min_width", "descriptionFallback": "Minimum width to prevent the panel from collapsing."}, {"name": "--origam-picker---padding-block", "defaultValue": "{space.4}", "descriptionKey": "components.picker.css_vars.padding_block", "descriptionFallback": "Top and bottom padding inside the panel."}, {"name": "--origam-picker---padding-inline", "defaultValue": "{space.4}", "descriptionKey": "components.picker.css_vars.padding_inline", "descriptionFallback": "Left and right padding inside the panel."}, {"name": "--origam-picker__title---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.picker.css_vars.title_color", "descriptionFallback": "Title strip text color."}, {"name": "--origam-picker__title---font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.picker.css_vars.title_font_size", "descriptionFallback": "Title strip font size."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.picker.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.picker.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "ROUNDED.X_SMALL", "value": "ROUNDED.X_SMALL"}, {"label": "x-small", "value": "x-small"}, {"label": "ROUNDED.SMALL", "value"