INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cd643ab9-71c9-4280-9df8-493e3102568e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'component', 'selection-control-group', 'SelectionControlGroup', 'Form & Input', NULL, 'mdi-format-list-checks', 'components.catalog.selection_control_group.description', 'Groups multiple SelectionControl instances under a shared v-model with inline layout support and a typed item-slot API.', NULL, NULL, 'origam-selection-control-group', NULL, 'packages/ds/src/components/SelectionControl/OrigamSelectionControlGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-selection-control--design', '/docs/components/SelectionControl/OrigamSelectionControl.html', 'selection-control', '{"a11y": {"notes": [{"noteKey": "components.selection_control_group.a11y.role_group", "noteFallback": "The root element carries role=\"group\" and is identified by the computed name/id attribute. Screen readers announce the group boundary."}, {"noteKey": "components.selection_control_group.a11y.defaults_provider", "noteFallback": "OrigamDefaultsProvider forwards type, name, density, color, disabled, readonly and error to every descendant SelectionControl. Child overrides still win."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.selection_control_group.a11y.key_tab", "actionFallback": "Moves focus through each child SelectionControl."}, {"key": "Space", "actionKey": "components.selection_control_group.a11y.key_space", "actionFallback": "Toggles the focused child control."}]}, "tokens": {"excerpt": [{"type": "other", "value": "flex", "tokenPath": "--origam-selection-