INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('83adb096-a76a-4cf5-9e58-4112b0dab264', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'composable', 'use-calendar', 'useCalendar', NULL, 'Calendar', 'mdi-calendar', '', 'Stateless calendar engine powering <OrigamCalendar>. Computes the visible date range for month/week/day/agenda views, expands recurring events (RRULE), and provides pure grid-builder functions for month, week, and day layouts. Navigation mutates the current date via optional callbacks so the composable can be driven from props, a store, or a local ref without re-instantiation.', NULL, 'function useCalendar(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5f7bea24-26ff-409a-8d3d-cb5732891ad4', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'composable', 'use-cell', 'useCell', NULL, 'DataTable', 'mdi-table-column', '', 'Resolve the padding for a DataTable cell based on the column definition. Special columns (data-table-select and data-table-expand) receive a fixed narrow padding; user-defined columns honour the column''s own padding setting; all others receive the default undefined (letting CSS tokens drive the spacing).', NULL, 'function useCell(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a1c76598-91cb-481c-bade-0c2bce251aa8', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'composable', 'use-chart', 'useChart', NULL, 'Chart', 'mdi-chart-line', '', 'Stateless SVG chart engine powering <OrigamChart>. Computes every render-time descriptor needed for cartesian, polar, pie/donut, radar, bar, scatter, and stacked variants: viewBox, pixel-mapping scales, gridline ticks, per-series path/rect/circle descriptors, resolved legend entries, and an interactive hover state. Driven entirely by thunk options so it reacts to props, stores, or computed refs without re-instantiation.', NULL, 'function useChart(options: IUseChartOptions): {
