INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1e147a8b-1c88-4d36-aa59-77c3e70c9698', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'composable', 'use-parallax-transform', 'useParallaxTransform', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Computes CSS transform strings for parallax layer elements based on normalised mouse-position coordinates. Supports five transform types: translate, rotate, depth (3-D tilt), depth-inv (inverted tilt), scale, scale-x, and scale-y. Consumed by OrigamParallax to animate child layers.', NULL, 'function useParallaxTransform(
