INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('43788616-7d12-4562-88ad-c6769307a40f', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'interface', 'i-media-controller-emits', 'IMediaControllerEmits', 'Events & Emits', NULL, NULL, 'interfaces.catalog.i_media_controller_emits.description', 'Emits surfaced by <OrigamMediaController>. The shell calls methods.* directly for the basic ops (toggle play, seek, set volume, set rate, toggle mute, request cast) — those do not bubble. These emits are the ones the parent must handle because the Controller does not own enough context.', 'export interface IMediaControllerEmits {
    (e: ''quality-change'', quality: string): void
    (e: ''download''): void
    (e: ''previous''): void
    (e: ''next''): void
    (e: ''update:loopMode'', mode: TAudioLoopMode): void
    (e: ''update:shuffle'', shuffle: boolean): void
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fe5c0efc-21fd-4ad3-8338-18cb256d6773', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'interface', 'i-media-controller-props', 'IMediaControllerProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_media_controller_props.description', 'Props for <OrigamMediaController> — the universal media-controls shell consumed by <OrigamVideo> and <OrigamAudio>. Purely presentational: it receives state and methods from the parent and emits intents back. Audio-specific controls (loop, shuffle, prev/next) are opt-in so video consumers see zero regression.', 'export interface IMediaControllerProps extends ICommonsComponentProps {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e6d84872-4451-49b3-95c9-39439b59df42', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'interface', 'i-media-controller-slots', 'IMediaControllerSlots', 'Slots', NULL, NULL, 'interfaces.catalog.i_media_controller_slots.description', 'Scoped slots exposed by <OrigamMediaController>. Consumers inject media-specific blocks: OrigamAudio injects header + waveform + footer; OrigamVideo injects captions/PiP/fullscreen through extraControlsRight.', 'export interface IMediaControllerSlots {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fdf23384-e5e3-4962-ad4b-8c1deb840460', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'interface', 'i-media-player-emits', 'IMediaPlayerEmits', 'Events & Emits', NULL, NULL, 'interfaces.catalog.i_media_player_emits.description', 'Shared media event signatures. Composables themselves do NOT emit — consumers wire their own emits from the state refs. This interface is kept for documentation and for components that want to surface the same shape on their public emit contract.', 'export interface IMediaPlayerEmits {
    (e: ''play''): void
    (e: ''pause''): void
    (e: ''ended''): void
    (e: ''timeupdate'', currentTime: number): void
    (e: ''volumechange'', volume: number): void
    (e: ''loadedmetadata'', payload: { duration: number }): void
    (e: ''error'', err: MediaError | Error): void
