INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('14b68237-3c83-4305-bddc-d8e7246c3d94', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '6f0f7a37-a85a-42cb-a3b8-d95c1e622784', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f607e93b-0ade-4b7c-8e00-3a9f535e9f91', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '6f0f7a37-a85a-42cb-a3b8-d95c1e622784', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b883b0fb-92ec-4caa-9e83-154bbc9cd39e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '6f0f7a37-a85a-42cb-a3b8-d95c1e622784', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('38c9185f-f4c3-4211-ad9e-4c0ec4b7be90', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '188a6b43-7d19-426d-8f1d-80de0251799a', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('735b00aa-c50d-42cd-84e5-56a684971a7e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '188a6b43-7d19-426d-8f1d-80de0251799a', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5f383396-8c1a-4135-b92f-4ebde4a9b698', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '188a6b43-7d19-426d-8f1d-80de0251799a', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9436ac26-b703-480c-af9b-19b2535841cb', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd26c32d1-6f7b-4d1d-a0a6-292c24c9f98e', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f854e272-bbb6-4cd4-b1c7-e5aef783afb6', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd26c32d1-6f7b-4d1d-a0a6-292c24c9f98e', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0dc13ee2-34d5-497c-b62e-f47744747575', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd26c32d1-6f7b-4d1d-a0a6-292c24c9f98e', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f65bdbc1-8fb4-4cdf-8b03-8e56e3dbe8c1', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '0fae111c-f03e-44ef-87fd-c35d253762d8', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47cbdca3-a746-40fd-bfbc-4835d04f6b9c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '3c3fd58a-4aca-491c-8e13-3c1d5a61f2c6', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9800a193-d620-423b-8ff2-f774f8dd2fdf', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '675982a0-de2a-4114-8773-663bbbcf5f50', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('81e53b21-8785-414e-9867-6015d224ef65', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd5e21fbc-d664-4396-8fec-efd87d0da61b', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
