INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a9a0cbf2-3f1e-418f-8551-fedd684028cf', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '83adb096-a76a-4cf5-9e58-4112b0dab264', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('848feebe-bab5-4515-92de-0cf001c10132', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '83adb096-a76a-4cf5-9e58-4112b0dab264', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
