INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aff00d3d-635a-4fab-8687-07f5949ebfcc', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '15d15887-1fcb-4a78-a189-637a80dadfc7', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('62f7c6a8-4c47-4c6c-ab47-1398ec73dadd', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1f47f45f-cf1c-4e69-bc08-3ec1bb2615ce', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bcc0235d-ad0d-4ada-9daf-7e0001fcc6a0', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c381709c-d1a3-4ae3-9839-56f8e503f9ce', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('24d9323b-3a08-4175-9dc2-63da66d9e575', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2a743e61-7f2f-4ddf-9f8d-90f9efd25fad', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b04b58e-d7f7-4bfd-8d6d-d1034b82de3c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('80d5cfe1-01d3-4899-91bc-c70528ec04b7', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '0509eb42-98b5-40d3-81d8-8f5a05a16ad8', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a3fdc87d-cd41-4a1c-ba65-376b96edd7d8', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '0509eb42-98b5-40d3-81d8-8f5a05a16ad8', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb580f9a-b1d3-4239-9399-a4bf1452e7ca', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd1220466-6c5d-4cd7-abea-a8802b7c637b', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('45e44512-5733-4560-81fa-182cee2030c3', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd1220466-6c5d-4cd7-abea-a8802b7c637b', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d96d424f-6dde-46ce-aa0f-514e620741cb', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'ef907aee-c0ac-4a82-967a-aaf0d99eefa5', 'rootEl', 'Ref<HTMLElement | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7141adba-0cc5-43cd-b0a3-ec6139ac664e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'ef907aee-c0ac-4a82-967a-aaf0d99eefa5', 'isSticky', 'Ref<boolean>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9e53e94a-ad06-49ab-af77-c0913638e07d', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'ef907aee-c0ac-4a82-967a-aaf0d99eefa5', 'layoutItemStyles', 'Ref<CSSProperties>', true, NULL, NULL, NULL, 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('56e2d263-4542-452b-8ba8-68a679632e39', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf890df4-f34f-4454-a4aa-0764ccca8f91', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f5f2250c-2338-4514-91e1-e4b59d8e6297', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf890df4-f34f-4454-a4aa-0764ccca8f91', 'uniq', 'MaybeRefOrGetter<string | undefined>', false, 'undefined', '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('750ba7bc-3ed0-4382-8cf3-edda2f4bd5d9', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf890df4-f34f-4454-a4aa-0764ccca8f91', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2872a25a-63d8-4bbe-bc6f-88aa8fa35537', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '3ed2a613-3247-4c79-adc8-615914070ca0', 'css', 'MaybeRef<string>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
