INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e0f25fa1-ad35-4e62-835f-774c820d1362', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'effb3d9a-2eb0-4b20-b983-138a51d7c66e', 'target', 'Ref<boolean | string | Element>', true, NULL, '', 'Reactive teleport destination. true → returns undefined (Vue Teleport disabled, renders in-place). false → document.body. A CSS selector string → querySelector result. An Element → used directly. Returns undefined and warns if a string selector yields no match.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5712d049-36c2-47b4-9ad6-facd9420456a', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '88d5e1b5-fb13-47a4-91a0-b6291e479c49', 'fieldRef', 'Ref<{ $el?: HTMLElement } | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
