INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c9a8f875-6333-4e2e-a289-2477bc1aca3c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'a550500a-b09b-40d9-80b4-fe9f673c4500', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('411f5d54-f4ef-489c-8c3b-412c9f17cf6d', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '9aa40a1a-541a-4dcc-8ae3-6d06ae5dc85d', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0bbd65bc-b0d7-4dc5-901e-66df037ff487', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '9aa40a1a-541a-4dcc-8ae3-6d06ae5dc85d', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a9732b6a-c764-4e3c-a76b-1e662e50d6cd', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '0dcc951a-afd1-44cc-b678-74a517174cb9', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a94d3b45-d3f8-4a0c-a44c-f99fb1180ed1', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '0dcc951a-afd1-44cc-b678-74a517174cb9', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('52631e41-4bfc-4fa2-afe3-b28dc855021e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '1a66df7e-8146-48a5-98b9-0fe4dcf8f02d', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1e380c55-f959-4b3e-9d00-e459cb8a7592', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '1a66df7e-8146-48a5-98b9-0fe4dcf8f02d', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f47e02f-c587-447e-b702-e5bef98f8a08', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'f93dc676-b1a1-43db-b730-a550235a6887', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9f4f2b50-786f-4f6c-ae40-d8f44ea16981', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'f93dc676-b1a1-43db-b730-a550235a6887', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('83ca78ab-54ad-4471-b43c-de257b329606', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'f93dc676-b1a1-43db-b730-a550235a6887', 'width', 'Ref<number>', true, NULL, '', 'Pixel width (or height for top/bottom positions) of the drawer. Used to compute drag progress as a fraction in [0, 1].', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a414a435-a61a-4f97-889f-86f5c1f0afb1', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'f93dc676-b1a1-43db-b730-a550235a6887', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
