INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0feb7bcd-93ff-4ee0-9c0b-cf7ba524e200', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('175677ac-2721-43a4-a55c-4e1a9a82c9e5', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e7e59e70-3927-4784-871b-a1913b10e7e4', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'cbc0b203-29d5-4b39-afed-30289483e535', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('12c3c440-bac3-47fe-b194-9b807a778c49', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'cbc0b203-29d5-4b39-afed-30289483e535', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
