INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0505f5db-12e3-48b6-b412-bdf96cef97d5', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'cbc0b203-29d5-4b39-afed-30289483e535', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d6c1c5a-a319-4648-acf0-a27a56914ba9', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'cbc0b203-29d5-4b39-afed-30289483e535', 'transformOut', '(value: Inner) => Props[Prop]', false, '(v: Inner) => v as Props[Prop]', '', 'Optional inverse transform applied before emitting `update:prop`. Pairs with transformIn to keep the internal representation separate from the public API value.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b852f2e6-d966-4a86-b640-777dae3c3320', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '61c4a2a1-cd58-4ccb-8996-bd51321a0f42', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('952f617c-2a85-475a-b9fe-1aadb7a188aa', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '85d3263d-58e7-42dc-8c4e-ae36abe9776f', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
