INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('55a41602-d0e5-41ca-b2b8-7da9aa85da83', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '2cb4e696-d689-4dfc-af1f-6399b3c50155', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
