INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0319c31e-6347-4307-a0e8-d0bc5a916944', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', 'd5c71689-0e08-42f1-82df-a3df85d1af77', 'root', 'string | number', '', 'primitive', NULL, false, 'undefined', 'components.defaults_provider.props.root.description', 'Marks the provider as a root scope — equivalent to reset but communicates intent: this is the top of a defaults tree, not a mid-tree override.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eabbf0a8-08a6-4706-9d52-3ffef389fd1d', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', 'd5c71689-0e08-42f1-82df-a3df85d1af77', 'scoped', 'boolean', '', 'primitive', NULL, false, 'undefined', 'components.defaults_provider.props.scoped.description', 'When true, parent defaults are not merged in — the subtree only sees this provider''s defaults. Same effect as reset but expressed declaratively.', 4, false, NULL, NULL);
