INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ba45ea7a-72c8-4b05-bb7a-28bcbe8fcaf3', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '579bfb6f-8ce6-4618-9fb1-cbc475800466', 'state', 'IMediaPlayerState', '', 'primitive', NULL, true, '—', 'components.media_controller.props.state.description', 'Reactive media state from useMediaPlayer() (or a specialisation: useVideoPlayer, useAudioPlayer). Contains refs for playing, currentTime, duration, volume, muted, buffered, playbackRate, remoteAvailable, remoteState.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c11d849-c81b-4ca7-8066-947847c9a88d', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '579bfb6f-8ce6-4618-9fb1-cbc475800466', 'methods', 'IMediaPlayerMethods', '', 'primitive', NULL, true, '—', 'components.media_controller.props.methods.description', 'Imperative methods from useMediaPlayer(). Provides play(), pause(), seek(), setVolume(), toggleMute(), setPlaybackRate(), requestRemotePlayback().', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9e110684-4439-48bf-b68d-0540c1066d1a', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '579bfb6f-8ce6-4618-9fb1-cbc475800466', 'inset', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.inset.description', 'YouTube-style overlay mode: the shell sits on top of the media surface with a dark gradient and auto-hides on visible=false. When false, renders as a regular always-on toolbar.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d600c46-0734-4969-a8c2-f3e0b766f6e0', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '579bfb6f-8ce6-4618-9fb1-cbc475800466', 'visible', 'boolean', '', 'primitive', NULL, false, 'true', 'components.media_controller.props.visible.description', 'Visibility flag driven by the parent autohide logic. Only meaningful when inset=true. When false, the shell is opacity: 0 and pointer-events: none.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('93ae2367-37b5-4b26-97cc-7c2cc733b916', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '579bfb6f-8ce6-4618-9fb1-cbc475800466', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', NULL, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b55451eb-862a-48f9-a127-a957616c3073', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '579bfb6f-8ce6-4618-9fb1-cbc475800466', 'allowRemotePlayback', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('12b3e49e-4ad8-44bc-8654-1f8fc027a6c6', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '579bfb6f-8ce6-4618-9fb1-cbc475800466', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
