INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eb96847d-fd15-44e8-9d0a-6bb6595eb8b2', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '579bfb6f-8ce6-4618-9fb1-cbc475800466', 'downloadFilename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
