INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('43f105d9-07d1-4444-b8c3-222338db6ead', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '3b5d4301-9f52-4a9d-92a6-8e99b6898355', 'step', 'number', '', 'primitive', NULL, false, '0', 'components.media_scrubber.props.step.description', 'Discrete step. 0 (default) means continuous — pointer events emit the raw float; positive values snap each emission to the nearest multiple.', 3, false, NULL, NULL);
