INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bf62bfb5-f9af-46b0-9432-6a5cbcc6e180', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '3b5d4301-9f52-4a9d-92a6-8e99b6898355', 'orientation', 'TMediaScrubberOrientation', '', 'primitive', NULL, false, '''horizontal''', 'components.media_scrubber.props.orientation.description', 'Layout axis. horizontal = YouTube timeline shape; vertical = volume / level meter shape (top of track = max, bottom = min).', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54b6753a-3dec-49dc-aa5b-b5aa8caf5103', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '3b5d4301-9f52-4a9d-92a6-8e99b6898355', 'disabled', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.disabled.description', 'Disables pointer + keyboard interaction. The element drops out of the tab order (tabindex="-1") and pointer events become no-ops.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f9eb1072-53d7-4425-9bab-7d2261be142e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:26.139661+00', '3b5d4301-9f52-4a9d-92a6-8e99b6898355', 'showThumbOnHoverOnly', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_thumb_on_hover_only.description', 'Hides the thumb at rest and reveals it on hover / focus / drag — the YouTube pattern. When false, the thumb is always visible.', 7, false, NULL, NULL);
