INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6082fc9b-4d3f-4341-874b-1a91701c5065', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '1d4c1b18-65a9-4a01-9ed2-c05008b23d1c', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0649cddd-12ad-4e72-a931-ffe6ac61e01a', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '1d4c1b18-65a9-4a01-9ed2-c05008b23d1c', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e2b05ab-403f-486f-84e0-0636a910f27c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '1d4c1b18-65a9-4a01-9ed2-c05008b23d1c', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b6c16240-f381-4e7c-8316-ad8790f3a0b4', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '1d4c1b18-65a9-4a01-9ed2-c05008b23d1c', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd9bfe12-7d2c-4976-8359-93e3b73b6052', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '1d4c1b18-65a9-4a01-9ed2-c05008b23d1c', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb353311-852f-46fc-a9c0-8abf790e1d4d', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'dcc7f291-a394-46e3-8344-681608464dcd', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a4bcf03d-8d01-4edf-808e-075c93ab6c11', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'dcc7f291-a394-46e3-8344-681608464dcd', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f58d519-522b-45a5-93e6-2468a17f6a47', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'dcc7f291-a394-46e3-8344-681608464dcd', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0ab11dce-1d31-4741-8824-154bdc4ef51f', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'dcc7f291-a394-46e3-8344-681608464dcd', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0802b737-4ad3-4fc9-bf65-2b6d2266dd0a', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '484d149b-31f7-4771-806d-97b5046ce91b', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0cbfd19f-defd-4654-845c-74d32a089e28', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '484d149b-31f7-4771-806d-97b5046ce91b', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ead98943-6019-4add-98ea-e879d6aea4d2', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '484d149b-31f7-4771-806d-97b5046ce91b', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54aedd2b-fda0-43e7-a521-cd8d3d9b2854', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '484d149b-31f7-4771-806d-97b5046ce91b', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fe583b19-0c30-4520-87e2-dfa6087a27b6', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '78bf26a1-3e0e-4c83-8935-bbdb641a19ae', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6700f137-057d-48df-b226-d1c22acacd62', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '78bf26a1-3e0e-4c83-8935-bbdb641a19ae', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c8b14b95-fbb8-4372-84fd-5389051ea777', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '78bf26a1-3e0e-4c83-8935-bbdb641a19ae', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c3325a25-d7dd-4a70-be8d-f4c79f9c709e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '0801fa15-49fc-492c-b15a-3d1c63c07506', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96ce8e33-7dd7-4572-b0d6-d4ff51b101e6', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '0801fa15-49fc-492c-b15a-3d1c63c07506', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1c058069-0b7a-4feb-b55e-2b771e2463ec', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '19a74b35-ae32-4324-91df-4acd1e282ade', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04a8082d-2659-4c07-912f-19df2b2478b2', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '15d15887-1fcb-4a78-a189-637a80dadfc7', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87f58e97-9068-46a3-88e2-c98052c38780', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '15d15887-1fcb-4a78-a189-637a80dadfc7', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('76211097-60a9-48ba-b5d7-fc293b1eaa1f', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '15d15887-1fcb-4a78-a189-637a80dadfc7', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('86164531-5f6a-44d8-9a09-afb9be40ebdd', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('17af058d-9be3-4bf0-8ddc-4c2956fb5804', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d3728b8a-2a1f-4acd-a5ec-dcb3ebd138b9', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('02c229b9-3976-4614-9ebd-bb9499bf3b02', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('031b88cb-b9ec-4c90-8371-b5f04355d4b5', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e68b5d85-46ee-41df-ac4f-1b714609f8d8', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1cdec49-42e0-4f5f-9751-eb10230b7ca0', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf69fae5-b11b-482c-b27a-67a9c0e0df8a', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b0e26e95-7c39-43a3-bdd8-9a73b6b001d3', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd1220466-6c5d-4cd7-abea-a8802b7c637b', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('45b702dc-8146-49bb-843f-34d82c1a8849', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd1220466-6c5d-4cd7-abea-a8802b7c637b', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7657cc5b-cd74-4807-8655-d9850badb690', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd1220466-6c5d-4cd7-abea-a8802b7c637b', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('645ed05c-b94b-4277-9bff-8fb793546995', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd1220466-6c5d-4cd7-abea-a8802b7c637b', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('71e7fe2a-d58c-4e8d-b1f4-8606abef9b88', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'd1220466-6c5d-4cd7-abea-a8802b7c637b', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('23cb77d0-7f33-48f2-adab-3325f170529f', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'ef907aee-c0ac-4a82-967a-aaf0d99eefa5', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('067b232c-919d-4e86-bf18-4d71be53ef0c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'ef907aee-c0ac-4a82-967a-aaf0d99eefa5', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c5cd7407-7fee-45d6-956c-f084f46169a6', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf890df4-f34f-4454-a4aa-0764ccca8f91', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('85a6d584-3f01-49fa-84e6-eea22a355981', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf890df4-f34f-4454-a4aa-0764ccca8f91', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9be51e47-3846-4402-bd41-ab6c7523a1f4', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf890df4-f34f-4454-a4aa-0764ccca8f91', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3265b120-d529-4f63-ab27-8a3cb3183fa1', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'bf890df4-f34f-4454-a4aa-0764ccca8f91', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0501d74a-3e4d-4aff-8e59-b4364183ece3', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'effb3d9a-2eb0-4b20-b983-138a51d7c66e', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('925ea252-db99-4873-8982-8584a05d5150', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'a550500a-b09b-40d9-80b4-fe9f673c4500', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f8db2f2a-50c0-4729-bfb6-d841224b6bdf', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'a550500a-b09b-40d9-80b4-fe9f673c4500', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('843403f9-6a97-45f1-adf3-d6feb7525e22', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'a550500a-b09b-40d9-80b4-fe9f673c4500', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e1418bcb-1949-4458-8925-9ab9de94ed3c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'a550500a-b09b-40d9-80b4-fe9f673c4500', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('82df9a3d-f7af-468d-aeb0-f3215cdf42cb', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'a550500a-b09b-40d9-80b4-fe9f673c4500', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7ca055ba-2c70-4fff-84e0-ddaa0ecd5d11', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'a550500a-b09b-40d9-80b4-fe9f673c4500', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bcec4052-ad47-409b-83b0-af30c6a2b6ee', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '9aa40a1a-541a-4dcc-8ae3-6d06ae5dc85d', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('801c9b0a-fb10-413c-ace5-6ffb8fa3c95c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '9aa40a1a-541a-4dcc-8ae3-6d06ae5dc85d', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f2fc3c0-fd1f-4c26-ae9f-864a6b088c01', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '80e11fa7-e3e0-4690-9417-3f44ee6acf56', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
