INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('23a4c341-85df-43f0-8451-f1bf784c0e9c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '53ba609c-caf6-4f3b-aecc-411bbdfac436', 'addMovement', '(e: TouchEvent) => void', '', 'Record a touchstart or touchmove event sample. Each touch point is tracked independently. Call this on every touchmove to build a time-stamped sample history.', 0, false, NULL, NULL);
