INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('72cc6203-7b39-4005-b096-14bc8138f6f7', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '53ba609c-caf6-4f3b-aecc-411bbdfac436', 'getVelocity', '(id: number) => { x: number; y: number; direction: string }', '', 'Compute the velocity vector for the given touch identifier from the recent sample history. Returns px/ms values for x and y axes and the dominant direction string. Throws if no samples are found for the id.', 2, false, NULL, NULL);
