INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc1652eb-e249-4e0a-beac-60e208aa2620', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '3fddbe98-997d-41dc-b3f5-6b009a634633', 'state', 'IVideoPlayerState', '', 'All IMediaPlayerState fields (playing, paused, currentTime, duration, buffered, volume, muted, ready, loading, error, playbackRate, remoteAvailable, remoteState) plus `fullscreen: Ref<boolean>` and `pip: Ref<boolean>`.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f06a106f-847d-4205-b9ac-134950ce2f83', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '3fddbe98-997d-41dc-b3f5-6b009a634633', 'methods', 'IVideoPlayerMethods', '', 'All IMediaPlayerMethods (play, pause, toggle, seek, setVolume, toggleMute, load, skipBackward, skipForward, setPlaybackRate, requestRemotePlayback, stopRemotePlayback) plus `enterFullscreen`, `exitFullscreen`, `toggleFullscreen`, `requestPip`, `exitPip`, `togglePip`.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('adc70a42-d609-4f04-9719-2a1fe7c1f353', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5bce905d-6b07-434c-b441-d3e5e7a48a75', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6c1b2c39-960d-4c10-8ea3-6fae4cafbe23', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
