INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aaebb336-6a81-4b25-952c-a82b90f5998d', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('35dbdb93-f101-4c63-b256-756b33c0083c', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ee7caaa3-b3e6-4593-b1f3-f37ab515e917', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5139b14d-6d83-4e0a-8380-0997f2b164a3', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'fa872712-7489-48e1-afc3-6d4783de9652', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('51fdda07-39b3-4d87-a082-1fb4ef09aa9e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', 'cbc0b203-29d5-4b39-afed-30289483e535', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0b40f342-235a-40d2-9e0d-a893d468e8d5', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '61c4a2a1-cd58-4ccb-8996-bd51321a0f42', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4079a86e-13a7-4448-88de-e11ade30d529', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '61c4a2a1-cd58-4ccb-8996-bd51321a0f42', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
