INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f1493be5-b96b-4367-aa2c-cffa1c92f435', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '85d3263d-58e7-42dc-8c4e-ae36abe9776f', 'peaks', 'Ref<Array<number>>', '', 'Array of `bins` values in [0, 1], where 1 is the loudest bucket in the track. Empty while computing or on error.', 0, false, NULL, NULL);
