INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e7b6124-6669-487d-80aa-e6d02dc32841', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '52f11036-333d-4b76-b4e7-6e8fc78ca25e', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7101d1c1-86bb-4775-95b3-c2adab6a2bfe', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '52f11036-333d-4b76-b4e7-6e8fc78ca25e', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3b9cc4a6-8452-4c99-8c53-e4313b26af08', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '52f11036-333d-4b76-b4e7-6e8fc78ca25e', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f54fdac-3c39-441f-a132-635778c14069', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '3be02215-d562-45f0-98f4-131147ba67bc', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7ded389b-af94-433e-befc-cbe4dec7bf0e', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '3be02215-d562-45f0-98f4-131147ba67bc', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20db6ab1-eeba-46e6-b9be-43a25d54541f', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '3be02215-d562-45f0-98f4-131147ba67bc', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fc50f1dd-9334-406a-8ac5-2b2b271a69e9', '2026-11-25 09:44:03.738735+00', '2026-11-25 09:44:03.738735+00', '3be02215-d562-45f0-98f4-131147ba67bc', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
